import { getLocalSetting, putLocalSetting } from '@atlantis/shared';

const DEFAULT_CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes

interface CacheEntry<T> {
  data: T;
  cachedAt: number;
}

/**
 * Fetch with an IndexedDB/Supabase cache. Returns cached data immediately if
 * fresh; fetches otherwise. Returns `null` on network / HTTP failure.
 *
 * Pass `ttlMs` to opt into a longer or shorter TTL than the 5-minute default.
 * Widgets that poll on a long interval (e.g. `OnThisDay` at 1 h) should pass
 * the same value as their `setInterval` period so cross-widget readers see a
 * coherent snapshot until the widget itself refreshes.
 */
export async function cachedFetch<T>(
  url: string,
  cacheKey: string,
  ttlMs: number = DEFAULT_CACHE_TTL_MS,
): Promise<T | null> {
  const raw = await getLocalSetting(`widget-cache:${cacheKey}`);
  if (raw) {
    try {
      const entry: CacheEntry<T> = JSON.parse(raw);
      if (Date.now() - entry.cachedAt < ttlMs) return entry.data;
    } catch { /* corrupted — refetch */ }
  }

  try {
    const res = await fetch(url);
    if (!res.ok) return null;
    const data: T = await res.json();
    const entry: CacheEntry<T> = { data, cachedAt: Date.now() };
    putLocalSetting(`widget-cache:${cacheKey}`, JSON.stringify(entry));
    return data;
  } catch {
    return null;
  }
}
