import { useState, useEffect, useCallback, useMemo } from 'react';
import styled from '@emotion/styled';
import { keyframes } from '@emotion/react';
import { theme, listDocs, navigateTo } from '@atlantis/shared';
import type { SavedDoc } from '@atlantis/shared';
import { WidgetShell, Button, Icon } from '@atlantis/ui';
import { createT, localizedTimeAgo } from '@atlantis/i18n';
import SHELL_KEYS from '../translations';

// ─── Types ────────────────────────────────────────────────────────────────────

interface ChatTurn {
  role: 'user' | 'assistant';
  content: string;
}

interface AskDoc {
  doc: SavedDoc;
  title: string;
  preview: string;
  age: string;
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Strip common Markdown syntax, leaving plain readable text.
 * Handles: fenced code blocks, inline code, bold/italic, links, headings,
 * blockquotes, ordered/unordered list markers, horizontal rules.
 */
function stripMarkdown(md: string): string {
  return md
    .replace(/```[\s\S]*?```/g, '')          // fenced code blocks
    .replace(/`[^`]*`/g, '')                  // inline code
    .replace(/#{1,6}\s+/g, '')                // headings
    .replace(/\*\*([^*]+)\*\*/g, '$1')        // bold **
    .replace(/__([^_]+)__/g, '$1')            // bold __
    .replace(/\*([^*]+)\*/g, '$1')            // italic *
    .replace(/_([^_]+)_/g, '$1')              // italic _
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1') // links
    .replace(/^>\s+/gm, '')                   // blockquotes
    .replace(/^[-*+]\s+/gm, '')              // unordered list markers
    .replace(/^\d+\.\s+/gm, '')              // ordered list markers
    .replace(/^-{3,}$/gm, '')                // hr
    .replace(/\s+/g, ' ')                    // collapse whitespace
    .trim();
}

function buildAskDoc(doc: SavedDoc, t: ReturnType<typeof createT>): AskDoc | null {
  let turns: ChatTurn[] = [];
  try {
    const parsed = JSON.parse(doc.content) as { turns?: ChatTurn[] };
    if (Array.isArray(parsed.turns)) turns = parsed.turns;
  } catch {
    return null;
  }
  if (turns.length === 0) return null;

  const firstUser = turns.find((t) => t.role === 'user');
  const lastAssistant = [...turns].reverse().find((t) => t.role === 'assistant');

  const rawTitle = doc.name?.trim() || firstUser?.content?.slice(0, 50) || '';
  const title = rawTitle || t('ask.widget.untitled');

  let preview: string;
  if (lastAssistant) {
    preview = stripMarkdown(lastAssistant.content).slice(0, 80);
  } else if (firstUser) {
    preview = `> ${firstUser.content.slice(0, 77)}`;
  } else {
    preview = '';
  }

  const age = localizedTimeAgo(new Date(doc.savedAt).toISOString(), t);

  return { doc, title, preview, age };
}

// ─── Animations ──────────────────────────────────────────────────────────────

const fadeIn = keyframes`
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: translateY(0); }
`;

// ─── Styled ──────────────────────────────────────────────────────────────────

const List = styled.div`
  display: flex;
  flex-direction: column;
  gap: 2px;
  animation: ${fadeIn} 0.3s ease both;
`;

const SessionRow = styled.button`
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  column-gap: ${theme.spacing.sm};
  row-gap: 2px;
  align-items: start;
  width: 100%;
  background: transparent;
  border: none;
  border-radius: ${theme.borderRadius.md};
  padding: ${theme.spacing.sm};
  cursor: pointer;
  text-align: left;
  transition: background ${theme.transitions.base};
  font: inherit;

  &:hover {
    background: ${theme.colors.sidebarHover};
  }

  &:focus-visible {
    outline: 2px solid ${theme.colors.accent};
    outline-offset: -1px;
  }
`;

const Title = styled.span`
  grid-column: 1;
  grid-row: 1;
  font-size: 13.5px;
  font-family: ${theme.typography.fontFamily};
  color: ${theme.colors.mainText};
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
`;

const AgeChip = styled.span`
  grid-column: 2;
  grid-row: 1;
  font-size: 10.5px;
  font-family: ${theme.typography.fontFamilyMono};
  color: ${theme.colors.mainTextFaint};
  white-space: nowrap;
  flex-shrink: 0;
`;

const Preview = styled.span`
  grid-column: 1 / -1;
  grid-row: 2;
  font-size: 12px;
  font-family: ${theme.typography.fontFamily};
  color: ${theme.colors.mainTextMuted};
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  line-height: 1.45;
`;

const EmptyState = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: ${theme.spacing.sm};
  padding: ${theme.spacing.lg} 0;
  text-align: center;
  flex: 1;
  animation: ${fadeIn} 0.3s ease both;
`;

const EmptyMsg = styled.p`
  font-size: ${theme.typography.fontSizeBase};
  color: ${theme.colors.mainTextMuted};
  line-height: 1.5;
  max-width: 240px;
  margin: 0;
`;

// ─── Component ───────────────────────────────────────────────────────────────

interface AskSessionsWidgetProps {
  locale: string;
}

export function AskSessionsWidget({ locale }: AskSessionsWidgetProps) {
  const t = useMemo(() => createT(locale === 'pt' ? 'pt' : 'en', SHELL_KEYS), [locale]);
  const [docs, setDocs] = useState<AskDoc[]>([]);
  const [loaded, setLoaded] = useState(false);

  const refresh = useCallback(async () => {
    const raw = await listDocs('ask');
    const built = raw
      .slice(0, 5)
      .map((d) => buildAskDoc(d, t))
      .filter((d): d is AskDoc => d !== null);
    setDocs(built);
    setLoaded(true);
  }, [t]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // Re-fetch when the tab becomes visible (user returns from Ask app)
  useEffect(() => {
    const onVisible = () => {
      if (document.visibilityState === 'visible') refresh();
    };
    document.addEventListener('visibilitychange', onVisible);
    return () => document.removeEventListener('visibilitychange', onVisible);
  }, [refresh]);

  if (!loaded) return null;

  return (
    <WidgetShell title={t('ask.widget.title')} accentColor={theme.suites.lab}>
      {docs.length === 0 ? (
        <EmptyState>
          <EmptyMsg>{t('ask.widget.empty')}</EmptyMsg>
          <Button
            variant="ghost"
            icon={<Icon name="sparkle" size={13} />}
            onClick={() => {
              // Dispatch palette-open event — listener is in App.tsx (atlantis:open-widget-picker
              // pattern). The Ask scope wiring on the listener side is a follow-up task once the
              // Ask app redesign lands.
              window.dispatchEvent(new CustomEvent('atlantis:open-palette', { detail: { scope: 'ask' } }));
            }}
          >
            {t('ask.widget.emptyCta')}
          </Button>
        </EmptyState>
      ) : (
        <List>
          {docs.map(({ doc, title, preview, age }) => (
            <SessionRow
              key={doc.id}
              onClick={() => navigateTo('ask', { session: String(doc.id) })}
              title={title}
            >
              <Title>{title}</Title>
              <AgeChip>{age}</AgeChip>
              {preview && <Preview>{preview}</Preview>}
            </SessionRow>
          ))}
        </List>
      )}
    </WidgetShell>
  );
}
