/** Visual grouping in the WidgetPicker — matches the 5 named app suites
 *  used by the header `SuitesMenu`, plus a `tools` catch-all. Keep this
 *  union in lock-step with `apps/shell/src/suites.ts` → `SUITE_SPECS`. */
export type WidgetSuite =
  | 'lab'     // AI / tech intel (techscope, HN)
  | 'vida'    // daily glance — weather, news, streak, pet, clocks, crypto, seismic
  | 'learn'   // discovery — on-this-day, wiki, trends
  | 'games'   // (no widgets today)
  | 'ent'     // movies / music
  | 'tools';  // shell utilities (quicklinks, live-data)

export interface WidgetDefinition {
  id: string;
  labelEn: string;
  labelPt: string;
  descriptionEn: string;
  descriptionPt: string;
  icon: string;
  /** Default width in grid columns (1 = narrow, 2 = wide) */
  defaultCols: 1 | 2;
  /** Maximum width in grid columns — widget won't exceed this span */
  maxCols: 1 | 2 | 3 | 4;
  /** Minimum height in px */
  minHeight: number;
  /** Bucket the widget falls into in the WidgetPicker filter tabs. */
  suite: WidgetSuite;
}

export interface WidgetInstance {
  id: string;
  /** references WidgetDefinition.id */
  widgetId: string;
}

