const Footer = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding-top: 6px;
  border-top: 1px solid ${theme.colors.border};
  font-size: 11px;
  font-family: ${theme.typography.fontFamilyMono};
  color: ${theme.colors.mainTextMuted};
`;

const FooterAccent = styled.span`
  color: ${theme.colors.accent};
  font-weight: 700;
`;

const EmptyText = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 1;
  font-size: 12px;
  color: ${theme.colors.mainTextMuted};
  text-align: center;
  padding: 0 ${theme.spacing.sm};
`;

const DAY_LETTERS_EN = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];
const DAY_LETTERS_PT = ['D', 'S', 'T', 'Q', 'Q', 'S', 'S'];

/** Consecutive-day streak ending today for a single mission. */
function missionStreak(progress: DailyProgress, mission: DailyMission): number {
  let n = 0;
  const cursor = new Date();
  // eslint-disable-next-line no-constant-condition
  while (true) {
    const iso = cursor.toISOString().slice(0, 10);
    if (!wasMissionDone(progress, mission.id, iso)) break;
    n += 1;
    cursor.setDate(cursor.getDate() - 1);
    if (n > 365) break; // safety
  }
  return n;
}

interface HabitsWidgetProps {
  locale: string;
}

export function HabitsWidget({ locale }: HabitsWidgetProps) {
  const lang: Locale = locale === 'pt' ? 'pt' : 'en';
  const t = useMemo(() => createT(lang, SHELL_KEYS), [lang]);
  const [progress, setProgress] = useState<DailyProgress | null>(null);

  const refresh = useCallback(() => {
    loadDailyProgress().then(setProgress);
  }, []);

  useEffect(() => {
    refresh();
    const onChange = (e: Event) => {
      const detail = (e as CustomEvent<DailyProgress>).detail;
      if (detail) setProgress(detail);
      else refresh();
    };
    const onFocus = () => refresh();
    window.addEventListener(DAILY_PROGRESS_EVENT, onChange);
    window.addEventListener('focus', onFocus);
    return () => {
      window.removeEventListener(DAILY_PROGRESS_EVENT, onChange);
      window.removeEventListener('focus', onFocus);
    };
  }, [refresh]);

  const days = useMemo(() => lastNDays(DAYS_SHOWN), []);
  const today = todayISO();

  // Only surface missions the user has actually engaged with — ever-completed,
  // not just "exists in the seed list". Stops a fresh install from showing
  // a wall of empty grids for missions the user never opted into.
  const everCompleted = useMemo(() => {
    if (!progress) return new Set<string>();
    const s = new Set<string>();
    for (const ids of Object.values(progress.history)) {
      for (const id of ids) s.add(id);
    }
    return s;
  }, [progress]);

  const open = () => { window.location.hash = '#/daily'; };

  if (!progress || everCompleted.size === 0) {
    return (
      <Wrapper onClick={open} title={t('habits.open')}>
        <Header>🎯 {t('habits.title')}</Header>
        <EmptyText>{t('habits.empty')}</EmptyText>
      </Wrapper>
    );
  }

  const missions = progress.missions
    .filter((m) => everCompleted.has(m.id))
    .slice(0, MISSIONS_SHOWN);

  const totalDoneThisWeek = missions.reduce(
    (acc, m) => acc + days.filter((d) => wasMissionDone(progress, m.id, d)).length,
    0,
  );

  const dayLetters = lang === 'pt' ? DAY_LETTERS_PT : DAY_LETTERS_EN;

  return (
    <Wrapper onClick={open} title={t('habits.open')}>
      <Header>
        <span>🎯 {t('habits.title')}</span>
        <span>{t('habits.last7')}</span>
      </Header>

      <DayHeaderRow>
        <span />
        <span />
        {days.map((d) => {
          const dow = new Date(`${d}T00:00:00`).getDay();
          return (
            <DayLetter key={d} isToday={d === today}>
              {dayLetters[dow]}
            </DayLetter>
          );
        })}
        <span />
      </DayHeaderRow>

      <Rows>
        {missions.map((m, i) => {
          const streak = missionStreak(progress, m);
          const tint = m.color ?? theme.colors.accent;
          const name = missionLabel(m, lang);
          return (
            <Row key={m.id} delay={i}>
              <Emoji>{m.emoji}</Emoji>
              <Name>{name}</Name>
              {days.map((d) => (
                <Cell
                  key={d}
                  done={wasMissionDone(progress, m.id, d)}
                  today={d === today}
                  tint={tint}
                />
              ))}
              <StreakNum hot={streak >= STREAK_HIGHLIGHT} lit={streak > 0}>
                {streak > 0 ? streak : '·'}
              </StreakNum>
            </Row>
          );
        })}
      </Rows>

      <Footer>
        <span>{t('habits.weekDone', { n: totalDoneThisWeek })}</span>
        <FooterAccent>{t('habits.openShort')} &rarr;</FooterAccent>
      </Footer>
    </Wrapper>
  );
}
