/**
 * Feature flags.
 *
 * Why this module:
 *   Some apps are disabled by default but need a per-user override that
 *   doesn't require a YAML edit (`stockpulse.enabled` is the first real
 *   user). `apps.config.yml` can now set `flag: '<name>'` on an app entry,
 *   and the shell resolves the flag through this module instead of reading
 *   `enabled: true/false` directly.
 *
 * Override precedence (first match wins):
 *   1. User override in `localStorage('shell:flag:<name>')` (`'true'` /
 *      `'false'`). Set/cleared via `setFlag(name, true | false | null)` —
 *      pass `null` to remove and fall back to the default.
 *   2. Compile-time `FLAG_DEFAULTS` below.
 *   3. `false`.
 *
 * Storage is deliberately `localStorage` (sync, user-local) instead of the
 * shared `getSetting`/`putSetting` so the resolver can run inside a
 * `useMemo` during render without an async effect.
 *
 * Adding a new flag:
 *   1. Add an entry to `FLAG_DEFAULTS` with the default boolean.
 *   2. Reference it from `apps.config.yml` (`flag: '<name>'`) OR call
 *      `resolveFlag('<name>')` anywhere that needs the current value.
 */

const STORAGE_PREFIX = 'shell:flag:';

/** Compile-time defaults. Keys are the flag names referenced from YAML. */
export const FLAG_DEFAULTS: Record<string, boolean> = {
  // Stockpulse currently proxies Yahoo through a Supabase Edge Function that
  // frequently breaks; keep it disabled by default until the free-API
  // rewrite lands. Enable locally via `setFlag('stockpulse.enabled', true)`.
  'stockpulse.enabled': true,
};

export function resolveFlag(name: string): boolean {
  try {
    const raw = localStorage.getItem(STORAGE_PREFIX + name);
    if (raw === 'true') return true;
    if (raw === 'false') return false;
  } catch {
    /* localStorage disabled (privacy mode / cross-origin iframe) */
  }
  return FLAG_DEFAULTS[name] ?? false;
}

/** Set `null` to remove the override and fall back to `FLAG_DEFAULTS`. */
export function setFlag(name: string, value: boolean | null): void {
  try {
    if (value === null) localStorage.removeItem(STORAGE_PREFIX + name);
    else localStorage.setItem(STORAGE_PREFIX + name, String(value));
  } catch {
    /* ignore */
  }
}

export function listFlags(): Record<string, boolean> {
  const result: Record<string, boolean> = {};
  for (const name of Object.keys(FLAG_DEFAULTS)) {
    result[name] = resolveFlag(name);
  }
  return result;
}
