import { putSetting, getSetting } from './db';

export const DAILY_PROGRESS_KEY = 'daily:progress';

export type MissionFrame = 'disc' | 'ring' | 'stamp' | 'hex' | 'polaroid';

export interface DailyMission {
  id: string;
  emoji: string;
  points: number;
  /** Translation key (takes precedence over `name`). For seeded missions. */
  translationKey?: string;
  /** Literal label — for user-created missions where no translation exists. */
  name?: string;
  frame?: MissionFrame;  // default: 'disc'
  color?: string;        // hex/css — default: theme.colors.accent
  time?: string;         // HH:mm — optional scheduled time for reminders
}

export interface DailyProgress {
  totalPoints: number;
  totalMissionsCompleted: number;
  completedToday: string[];
  streakDays: string[];
  lastResetDate: string;
  missions: DailyMission[];
  /**
   * Per-day completion log. Keys are YYYY-MM-DD, values are the mission ids
   * that were checked off that day. The record is the canonical source for
   * week/month analytics; `completedToday` and `streakDays` are convenience
   * projections kept in sync for the current UI.
   */
  history: Record<string, string[]>;
}

export function todayISO(): string {
  return new Date().toISOString().slice(0, 10);
}

export function computeDailyStreak(streakDays: string[]): number {
  if (streakDays.length === 0) return 0;
  const sorted = [...new Set(streakDays)].sort().reverse();
  const today = todayISO();
  let streak = 0;
  let expected = today;
  for (const day of sorted) {
    if (day === expected) {
      streak++;
      const d = new Date(expected);
      d.setDate(d.getDate() - 1);
      expected = d.toISOString().slice(0, 10);
    } else {
      break;
    }
  }
  return streak;
}

export const STREAK_THRESHOLD = 3;

export function deriveStreakDays(
  history: Record<string, string[]>,
  threshold: number = STREAK_THRESHOLD,
): string[] {
  if (!history) return [];
  const out: string[] = [];
  for (const [day, ids] of Object.entries(history)) {
    if (ids && ids.length >= threshold) out.push(day);
  }
  return out;
}

export function computeStreakFromHistory(
  history: Record<string, string[]>,
  threshold: number = STREAK_THRESHOLD,
): number {
  return computeDailyStreak(deriveStreakDays(history, threshold));
}

export async function loadDailyProgress(): Promise<DailyProgress | null> {
  try {
    const raw = await getSetting(DAILY_PROGRESS_KEY);
    if (!raw) return null;
    return JSON.parse(raw) as DailyProgress;
  } catch {
    return null;
  }
}

export const DAILY_PROGRESS_EVENT = 'atlantis:daily-progress-change';

/** Returns YYYY-MM-DD keys for the last N days ending today (inclusive), oldest first. */
export function lastNDays(n: number, from: Date = new Date()): string[] {
  const out: string[] = [];
  for (let i = n - 1; i >= 0; i--) {
    const d = new Date(from);
    d.setDate(d.getDate() - i);
    out.push(d.toISOString().slice(0, 10));
  }
  return out;
}

export interface DayStat {
  date: string;            // YYYY-MM-DD
  completedIds: string[];  // mission ids done that day
  count: number;
}

/** Pulls N recent days from history, filling missing days with empty arrays. */
export function getDailyHistory(progress: DailyProgress, days: number): DayStat[] {
  return lastNDays(days).map((date) => {
    const ids = progress.history[date] ?? [];
    return { date, completedIds: ids, count: ids.length };
  });
}

/** True when the given mission was completed on the given YYYY-MM-DD. */
export function wasMissionDone(progress: DailyProgress, missionId: string, date: string): boolean {
  return progress.history[date]?.includes(missionId) ?? false;
}

/**
 * Missions with a scheduled `time` (HH:mm) that has already passed today and
 * are not yet marked completed. Used by the shell notification bell to surface
 * reminders — returns the mission plus its scheduled epoch ms so consumers can
 * sort / display relative time without re-parsing.
 */
export interface OverdueMission {
  mission: DailyMission;
  dueAt: number; // epoch ms for today's scheduled time
}

export function getOverdueMissions(
  progress: DailyProgress,
  now: Date = new Date(),
): OverdueMission[] {
  const out: OverdueMission[] = [];
  const today = todayISO();
  const doneToday = new Set(progress.lastResetDate === today ? progress.completedToday : []);
  for (const mission of progress.missions) {
    if (!mission.time) continue;
    if (doneToday.has(mission.id)) continue;
    const [hStr, mStr] = mission.time.split(':');
    const h = Number(hStr);
    const m = Number(mStr);
    if (!Number.isFinite(h) || !Number.isFinite(m)) continue;
    const due = new Date(now);
    due.setHours(h, m, 0, 0);
    if (due.getTime() > now.getTime()) continue;
    out.push({ mission, dueAt: due.getTime() });
  }
  out.sort((a, b) => b.dueAt - a.dueAt); // newest-due first
  return out;
}

/**
 * Bilingual labels for the seed missions. Single source of truth — both the
 * Daily app's translations and the shell's HabitsWidget reference these so
 * the strings can't drift apart. App-specific UI keys (modals, headings, etc.)
 * still live in each app's own translations.ts.
 */
export const SEEDED_MISSION_LABELS: Record<string, { en: string; pt: string }> = {
  'daily.mission.brushTeeth':  { en: 'Brush teeth',         pt: 'Lavar os dentes' },
  'daily.mission.makeBed':     { en: 'Make bed',            pt: 'Fazer a cama' },
  'daily.mission.read':        { en: 'Read for 15 min',     pt: 'Ler 15 minutos' },
  'daily.mission.tidyRoom':    { en: 'Tidy room',           pt: 'Arrumar o quarto' },
  'daily.mission.setTable':    { en: 'Help set table',      pt: 'Ajudar a pôr a mesa' },
  'daily.mission.schoolBag':   { en: 'Pack school bag',     pt: 'Preparar a mochila' },
  'daily.mission.vegetables':  { en: 'Eat vegetables',      pt: 'Comer legumes' },
  'daily.mission.clothesAway': { en: 'Put clothes away',    pt: 'Guardar a roupa' },
  'daily.mission.homework':    { en: 'Do homework',         pt: 'Fazer os trabalhos' },
  'daily.mission.draw':        { en: 'Draw or paint',       pt: 'Desenhar ou pintar' },
  'daily.mission.beKind':      { en: 'Be kind to someone',  pt: 'Ser gentil com alguém' },
};

/**
 * Resolve the user-facing name of a mission. Honours the seed translation map
 * when `translationKey` matches; otherwise falls back to the literal `name`
 * field used for user-created missions.
 */
export function missionLabel(mission: DailyMission, locale: 'en' | 'pt'): string {
  if (mission.translationKey) {
    const seeded = SEEDED_MISSION_LABELS[mission.translationKey];
    if (seeded) return seeded[locale];
  }
  return mission.name ?? '';
}

export async function saveDailyProgress(progress: DailyProgress): Promise<void> {
  try {
    await putSetting(DAILY_PROGRESS_KEY, JSON.stringify(progress));
    if (typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent<DailyProgress>(DAILY_PROGRESS_EVENT, { detail: progress }));
    }
  } catch {
    // ignore — non-fatal
  }
}
