// Apps that should NOT appear in the home dashboard or the suite-browse view.
// `visibilityOf` handles back-compat with the legacy `homeHidden: true` flag.
const HOME_HIDDEN = new Set(
  APP_CONFIG.filter((a) => {
    const v = visibilityOf(a);
    return v !== 'default';
  }).map((a) => a.id),
);

const VISIBLE_CONFIG = APP_CONFIG.filter((a) => a.enabled && visibilityOf(a) === 'default');

const CATEGORY_ORDER = ['All', 'Live', 'School', 'Explore', 'Create', 'Inspect', 'Connect', 'Content', 'Fun', 'Lab'];

const SUITE_ORDER = ['AI Lab', 'Data Studio', 'Life Dashboard', 'Learning Hub', 'Game Room', 'Entertainment'];
const ALL_SUITES = SUITE_ORDER.filter((s) =>
  VISIBLE_CONFIG.some((a) => APP_META[a.id]?.suite === s),
);

function greeting(locale: Locale, date: Date = new Date()): string {
  const h = date.getHours();
  const key = h < 12 ? 'greeting.morning' : h < 19 ? 'greeting.afternoon' : 'greeting.evening';
  return t(key, locale);
}

