// ─── Component ──────────────────────────────────────────────────────────────

export interface WidgetPickerProps {
  open: boolean;
  activeIds: Set<string>;
  locale: Locale;
  onAdd: (widgetId: string) => void;
  onRemove: (widgetId: string) => void;
  onClose: () => void;
}

export function WidgetPicker({
  open,
  activeIds,
  locale,
  onAdd,
  onRemove,
  onClose,
}: WidgetPickerProps) {
  const t: TFunction = useMemo(() => createT(locale, SHELL_KEYS), [locale]);
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState<WidgetSuite | 'all'>('all');
  const inputRef = useRef<HTMLInputElement | null>(null);

  useEffect(() => {
    if (open) {
      setQuery('');
      setFilter('all');
      requestAnimationFrame(() => inputRef.current?.focus());
    }
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [open, onClose]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return WIDGET_REGISTRY.filter((def) => {
      if (filter !== 'all' && def.suite !== filter) return false;
      if (!q) return true;
      const label = locale === 'pt' ? def.labelPt : def.labelEn;
      const desc  = locale === 'pt' ? def.descriptionPt : def.descriptionEn;
      return (
        label.toLowerCase().includes(q) ||
        desc.toLowerCase().includes(q) ||
        def.id.toLowerCase().includes(q) ||
        def.suite.toLowerCase().includes(q)
      );
    });
  }, [query, filter, locale]);

  if (!open) return null;

  return ReactDOM.createPortal(
    <Backdrop onClick={onClose}>
      <Panel onClick={(e) => e.stopPropagation()} role="dialog" aria-label={t('widgets.picker.title')}>
        <Header>
          <HeaderTop>
            <Eyebrow>{t('widgets.picker.eyebrow')}</Eyebrow>
            <CloseBtn onClick={onClose} aria-label={t('widgets.picker.close')}>
              <Icon name="close" size={14} aria-hidden="true" />
            </CloseBtn>
          </HeaderTop>
          <Title>{t('widgets.picker.title')}</Title>
          <Subtitle>{t('widgets.picker.subtitle')}</Subtitle>
        </Header>

        <Controls>
          <Input
            ref={inputRef}
            placeholder={t('widgets.picker.searchPlaceholder')}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            before={<Icon name="search" size={14} aria-hidden="true" />}
          />
          <ChipRow role="tablist">
            {SUITE_CHIPS.map((c) => (
              <ChipBtn
                key={c.id}
                active={filter === c.id}
                chipColor={c.color}
                onClick={() => setFilter(c.id)}
                role="tab"
                aria-selected={filter === c.id}
              >
                {c.color && <span className="dot" />}
                {t(c.labelKey)}
              </ChipBtn>
            ))}
          </ChipRow>
        </Controls>

        <Grid>
          {filtered.length === 0 ? (
            <Empty>{t('widgets.picker.empty')}</Empty>
          ) : (
            filtered.map((def) => {
              const added = activeIds.has(def.id);
              const label = locale === 'pt' ? def.labelPt : def.labelEn;
              const desc  = locale === 'pt' ? def.descriptionPt : def.descriptionEn;
              const accent = SUITE_COLOR[def.suite];
              const suiteChip = SUITE_CHIPS.find((c) => c.id === def.suite);
              return (
                <Card
                  key={def.id}
                  added={added}
                  onClick={() => {
                    if (added) onRemove(def.id);
                    else onAdd(def.id);
                  }}
                >
                  <CardHeader>
                    <CardEmoji>{def.icon}</CardEmoji>
                    <CardTitle>{label}</CardTitle>
                    {added && (
                      <AddedBadge>
                        <Icon name="check" size={10} aria-hidden="true" />
                        {t('widgets.picker.added')}
                      </AddedBadge>
                    )}
                  </CardHeader>
                  <CardDesc>{desc}</CardDesc>
                  <CardMeta>
                    <SuiteSwatch swatchColor={accent} />
                    {suiteChip ? t(suiteChip.labelKey) : def.suite}
                  </CardMeta>
                </Card>
              );
            })
          )}
        </Grid>
      </Panel>
    </Backdrop>,
    document.body,
  );
}
