function RemoteErrorView({
  name,
  error,
  topBarRight,
  onRetry,
}: {
  name: string;
  error: Error;
  topBarRight?: React.ReactNode;
  onRetry: () => void;
}) {
  const [locale] = useLocale();
  const t = useMemo(() => createT(locale, SHELL_KEYS), [locale]);

  const msg = error.message ?? '';
  const isLoadFailure = msg.startsWith('REMOTE_LOAD_FAILED:');
  const failedId = isLoadFailure ? msg.slice('REMOTE_LOAD_FAILED:'.length) : name;
  const isDev = process.env.NODE_ENV !== 'production';

  const labelKey = `apps.${failedId}.label`;
  const translated = t(labelKey);
  const appLabel = translated && translated !== labelKey ? translated : failedId;

  const subKey = !isLoadFailure
    ? 'error.remote.generic'
    : isDev
      ? 'error.remote.devHint'
      : 'error.remote.prodHint';

  return (
    <Layout title={appLabel} sidebar={null} topBarRight={topBarRight}>
      <ErrorScreen>
        <ErrorIcon>⚠</ErrorIcon>
        <ErrorTitle>{t('error.remote.title', { name: appLabel })}</ErrorTitle>
        <ErrorSub>{t(subKey)}</ErrorSub>
        {isLoadFailure && isDev && <ErrorCode>pnpm dev:{failedId}</ErrorCode>}
        <div style={{ display: 'flex', gap: theme.spacing.sm }}>
          <HomeBtn onClick={onRetry}>{t('error.remote.retry')}</HomeBtn>
          <HomeBtn onClick={() => { window.location.hash = '#/home'; }}>
            {t('error.remote.goHome')}
          </HomeBtn>
        </div>
      </ErrorScreen>
    </Layout>
  );
}

interface RemoteErrorBoundaryState {
  error: Error | null;
}

class RemoteErrorBoundary extends React.Component<
  { name: string; topBarRight?: React.ReactNode; children: React.ReactNode },
  RemoteErrorBoundaryState
> {
  state: RemoteErrorBoundaryState = { error: null };

  static getDerivedStateFromError(error: Error): RemoteErrorBoundaryState {
    return { error };
  }

  componentDidCatch(error: Error) {
    console.error(`[RemoteErrorBoundary] "${this.props.name}" threw:`, error);
  }

  componentDidUpdate(prev: { name: string }) {
    // Reset when navigating to a different app.
    if (prev.name !== this.props.name && this.state.error) {
      this.setState({ error: null });
    }
  }

  render() {
    if (this.state.error) {
      return (
        <RemoteErrorView
          name={this.props.name}
          error={this.state.error}
          topBarRight={this.props.topBarRight}
          onRetry={() => this.setState({ error: null })}
        />
      );
    }
    return this.props.children;
  }
}

// ─── Hash routing ──────────────────────────────────────────────────────────
//
// Primary hash (`hash: '#/games'`) and any `hashAliases: [...]` in
// apps.config.yml both resolve to the app id. `#/settings` is a pseudo-route
// (no remote — shell renders SettingsPage inline).

const HASH_TO_APP: Record<string, string> = (() => {
  const map: Record<string, string> = { settings: 'settings' };
  for (const app of APP_CONFIG) {
    const primary = app.hash.replace(/^#\//, '');
    map[primary] = app.id;
    for (const alias of app.hashAliases ?? []) map[alias] = app.id;
  }
  return map;
})();

function getAppFromHash(hash: string): string {
  const path = hash.replace(/^#\/?/, '');
  if (!path || path === 'home') return 'home';
  const first = path.split('/')[0].split('?')[0];
  return HASH_TO_APP[first] ?? 'home';
}

const RECENT_APPS_KEY = 'shell:recent';
const PINNED_APPS_KEY = 'shell:pinned';
const LAST_APP_KEY = 'shell:last-app';
const RECENT_MAX = 8;

/**
 * On first mount, if the user loaded the shell with no specific hash
 * (fresh tab, bookmark at `/`, or direct visit), restore the last-opened
 * app from synchronous localStorage. Respects explicit `#/home` so
 * clicking Home always lands on home.
 */
function initialActiveAppId(): string {
  const hash = window.location.hash;
  const bare = !hash || hash === '#' || hash === '#/';
  if (bare) {
    try {
      const last = localStorage.getItem(LAST_APP_KEY);
      if (last && last !== 'home' && REMOTES[last]) {
        const entry = APP_CONFIG.find((a) => a.id === last);
        if (entry) {
          // Use replaceState so the back button doesn't get a phantom
          // empty-hash entry to return to.
          history.replaceState(null, '', entry.hash);
          return last;
        }
      }
    } catch { /* ignore — fall through to home */ }
  }
  return getAppFromHash(hash);
}

function parseIds(raw: string | null): string[] {
  try { return JSON.parse(raw ?? '[]'); } catch { return []; }
}


const NEEDS_AUTH = new Set(
  APP_CONFIG.filter((a) => a.needsAuth).map((a) => a.id)
);

const MOCK_USER = process.env.MOCK_USER === 'true' ? {
  id: 'mock-user',
  email: 'dev@atlantis.local',
  user_metadata: { full_name: 'Dev User', avatar_url: '' },
} as unknown as User : null;
const TMDB_API_KEY = process.env.TMDB_API_KEY || '';

export default function App() {
  const [activeAppId,   setActiveAppId]   = useState(initialActiveAppId);
  const [recentApps,    setRecentApps]    = useState<string[]>([]);
  const [pinnedApps,    setPinnedApps]    = useState<string[]>([]);
  const [user,          setUser]          = useState<User | null>(MOCK_USER);
  const [authReady,     setAuthReady]     = useState(!!MOCK_USER);
  const [showPalette,   setShowPalette]   = useState(false);
  const [paletteScope,  setPaletteScope]  = useState<PaletteScope | undefined>(undefined);
  const [showProfile,   setShowProfile]   = useState(false);
  const [locale, setLocale]              = useLocale();
  const t = useMemo(() => createT(locale, SHELL_KEYS), [locale]);
  const formatDailyReminder = useCallback(
    (mission: DailyMission) => {
      const name = missionLabel(mission, locale);
      const displayName = mission.emoji ? `${mission.emoji} ${name}`.trim() : name;
      return {
        title: t('notifications.source.daily'),
        body: t('notifications.daily.body', { time: mission.time ?? '', name: displayName }),
      };
    },
    [t, locale],
  );
  const notifBell                         = useNotificationBell({ formatDailyReminder });
  const [notifAnchor, setNotifAnchor]    = useState<DOMRect | null>(null);

  // Subscribe to Supabase auth state and switch storage provider accordingly
  useEffect(() => {
    if (MOCK_USER) return; // skip Supabase in mock mode
    supabase.auth.getSession().then(({ data }) => {
      const u = data.session?.user ?? null;
      setUser(u);
      setStorageProvider(u ? supabaseProvider : null);
      setAuthReady(true);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      const u = session?.user ?? null;
      setUser(u);
      setStorageProvider(u ? supabaseProvider : null);
    });
    return () => subscription.unsubscribe();
  }, []);

  // Load persisted state from IDB on mount
  useEffect(() => {
    getSetting(RECENT_APPS_KEY).then((v) => setRecentApps(parseIds(v)));
    getSetting(PINNED_APPS_KEY).then((v) => setPinnedApps(parseIds(v)));
  }, []);

  // Cmd+K / Ctrl+K → open command palette
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        setPaletteScope(undefined);
        setShowPalette((v) => !v);
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, []);

  // Programmatic palette open — widgets / empty states dispatch
  // `atlantis:open-palette` (optionally `{ detail: { scope } }`) to surface
  // the palette and land on a specific tab (e.g. AskSessionsWidget → 'ask').
  useEffect(() => {
    const onOpen = (e: Event) => {
      const detail = (e as CustomEvent<{ scope?: PaletteScope }>).detail;
      setPaletteScope(detail?.scope);
      setShowPalette(true);
    };
    window.addEventListener('atlantis:open-palette', onOpen);
    return () => window.removeEventListener('atlantis:open-palette', onOpen);
  }, []);

  useEffect(() => {
    const onHashChange = () => setActiveAppId(getAppFromHash(window.location.hash));
    window.addEventListener('hashchange', onHashChange);
    return () => window.removeEventListener('hashchange', onHashChange);
  }, []);

  // Track recently used whenever activeAppId changes (skip 'home')
  useEffect(() => {
    if (!activeAppId || activeAppId === 'home') return;
    // Remember for "restore on next cold load". Synchronous localStorage so
    // `initialActiveAppId` can read it without an async round-trip.
    try { localStorage.setItem(LAST_APP_KEY, activeAppId); } catch {}
    setRecentApps((prev) => {
      const next = [activeAppId, ...prev.filter((id) => id !== activeAppId)].slice(0, RECENT_MAX);
      putSetting(RECENT_APPS_KEY, JSON.stringify(next));
      return next;
    });
  }, [activeAppId]);

  const handleNavigate = useCallback((hash: string) => {
    window.location.hash = hash;
    setShowPalette(false);
    setPaletteScope(undefined);
  }, []);

  const handleTogglePin = (appId: string) => {
    setPinnedApps((prev) => {
      const next = prev.includes(appId) ? prev.filter((id) => id !== appId) : [...prev, appId];
      putSetting(PINNED_APPS_KEY, JSON.stringify(next));
      return next;
    });
  };

  const handleMovePinned = (appId: string, direction: -1 | 1) => {
    setPinnedApps((prev) => {
      const idx = prev.indexOf(appId);
      if (idx < 0) return prev;
      const newIdx = idx + direction;
      if (newIdx < 0 || newIdx >= prev.length) return prev;
      const next = [...prev];
      [next[idx], next[newIdx]] = [next[newIdx], next[idx]];
      putSetting(PINNED_APPS_KEY, JSON.stringify(next));
      return next;
    });
  };

  // Suites menu — nav target for non-Games suites is the home "all apps"
  // view filtered by suite. We carry the suite id through the URL so it
  // survives a refresh; HomeScreen reads it from the hash query.
  const handleHomeSuite = useCallback((suiteId: string) => {
    window.location.hash = `#/home?suite=${encodeURIComponent(suiteId)}`;
  }, []);
  // Apply the Preferences interest filter at the shell boundary so the
  // `SuitesMenu` count, `CommandPalette` apps list, and `HomeScreen` apps
  // grid all see the same subset. Apps without an `interest` tag stay
  // visible regardless of selected interests.
  const [profile] = useProfile();
  const enabledApps = useMemo(
    () => APP_CONFIG
      .filter((app) => (app.flag ? resolveFlag(app.flag) : app.enabled))
      // Visibility `'hidden'` drops the app from every surface (home,
      // palette, suite). `'search-only'` and `'hidden-home'` still belong
      // in `enabledApps` — HomeScreen and the palette filter further on
      // their own.
      .filter((app) => visibilityOf(app) !== 'hidden')
      .filter((app) => {
        if (!hasInterests(profile)) return true;
        if (!app.interest) return true;
        return profile.interests.includes(app.interest);
      }),
    [profile],
  );
  const suiteEntries = useSuites(enabledApps, t, handleHomeSuite);
  const visibleSuiteEntries = useMemo(
    () => suiteEntries.filter((s) => s.count > 0),
    [suiteEntries],
  );

  // Palette adapters — suites → PaletteSuite, games → PaletteGame, shell
  // actions. `useThemeMode` would be the way to wire a real theme-toggle
  // action; defer that polish and expose the settings+preferences shortcuts
  // for now.
  const paletteSuites = useMemo<PaletteSuite[]>(
    () =>
      visibleSuiteEntries.map((s) => ({
        id: s.id,
        name: s.name,
        sub: s.subtitle,
        color: s.color,
        iconName: s.icon,
        onConfirm: () => handleHomeSuite(s.id),
      })),
    [visibleSuiteEntries, handleHomeSuite],
  );

  const paletteGames = useMemo<PaletteGame[]>(
    () =>
      GAMES_CHILDREN.map((g) => ({
        id: g.id,
        name: t(g.labelKey),
        glyph: g.glyph,
        hash: g.hash,
      })),
    [t],
  );

  const paletteActions = useMemo<PaletteAction[]>(
    () => [
      {
        id: 'add-widget',
        label: t('palette.action.addWidget'),
        meta: t('palette.action.addWidget.meta'),
        iconName: 'plus',
        color: theme.colors.accent,
        onClick: () => {
          window.location.hash = '#/home';
          requestOpenWidgetPicker();
        },
      },
      {
        id: 'preferences',
        label: t('palette.action.preferences'),
        meta: t('palette.action.preferences.meta'),
        iconName: 'settings',
        onClick: () => setShowProfile(true),
      },
      {
        id: 'settings',
        label: t('palette.action.settings'),
        meta: t('palette.action.settings.meta'),
        iconName: 'sparkle',
        onClick: () => { window.location.hash = '#/settings'; },
      },
      {
        id: 'language',
        label: t('palette.action.language'),
        meta: locale === 'pt' ? 'PT → EN' : 'EN → PT',
        iconName: 'globe',
        onClick: () => setLocale(locale === 'pt' ? 'en' : 'pt'),
      },
      ...(notifBell.count > 0
        ? [{
            id: 'clear-notifications',
            label: t('palette.action.clearNotifications'),
            meta: t('palette.action.clearNotifications.meta', { n: notifBell.count }),
            iconName: 'bell' as const,
            color: theme.colors.accent,
            onClick: () => { void notifBell.markAllRead(); },
          }]
        : []),
      ...(user
        ? [{
            id: 'signout',
            label: t('palette.action.signout'),
            meta: user.email ?? '',
            iconName: 'arrow-up-right' as const,
            color: theme.colors.danger,
            onClick: () => { void signOut(); },
          }]
        : []),
    ],
    [t, locale, setLocale, user, notifBell],
  );

  const [groqKey, setGroqKey] = useState<string | null>(null);
  useEffect(() => {
    void resolveGroqKey().then(setGroqKey);
  }, []);
  const hasAsk = hasEnvGroqKey() || !!groqKey;

  // Translate app label/description at the shell boundary so consumers
  // (HomeScreen, CommandPalette, AuthGate) keep receiving display strings.
  const APPS: AppDefinition[] = useMemo(
    () => enabledApps.map(({ id, labelKey, hash }) => ({ id, label: t(labelKey), hash })),
    [enabledApps, t],
  );

  const PALETTE_APPS: AppEntry[] = useMemo(
    () =>
      enabledApps
        .map(({ id, labelKey, descriptionKey, hash, icon, color, category }) => ({
          id,
          label: t(labelKey),
          description: t(descriptionKey),
          hash,
          icon,
          color,
          category,
        })),
    [enabledApps, t],
  );

  const appLabel = (() => {
    const entry = APP_CONFIG.find((a) => a.id === activeAppId);
    return entry ? t(entry.labelKey) : activeAppId;
  })();

  // Block access to protected apps until auth is ready, then gate if unauthenticated
  if (!authReady) return <ThemeProvider><LoadingScreen /></ThemeProvider>;

  if (NEEDS_AUTH.has(activeAppId) && !user) {
    return (
      <ThemeProvider>
        <AuthGate
          appLabel={appLabel}
          onBack={() => { window.location.hash = '#/home'; }}
        />
      </ThemeProvider>
    );
  }

  const liveCount = LIVE_FEED_COUNT[activeAppId];

  const handleBellClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    setNotifAnchor(e.currentTarget.getBoundingClientRect());
    notifBell.toggle();
  };

  // Unified header chrome — identical layout on home and in every remote app.
  // See `@atlantis/ui` → HeaderRight + UserMenu + docs/ui.md.
  const topBarRight = (
    <HeaderRight
      locale={locale}
      onLocaleChange={setLocale}
      before={liveCount != null ? <LiveIndicator count={liveCount} /> : undefined}
      suites={{
        entries: visibleSuiteEntries,
        label: t('suites.label'),
        ariaLabel: t('suites.aria'),
        appsLabel: t('suites.appsCount'),
      }}
      notifications={{
        count: notifBell.count,
        onClick: handleBellClick,
        label: t('notifications.bell'),
      }}
      onOpenPalette={() => { setPaletteScope(undefined); setShowPalette(true); }}
      paletteLabel={t('palette.search')}
      user={user ? {
        name: user.user_metadata?.full_name,
        email: user.email ?? '',
        avatarUrl: user.user_metadata?.avatar_url,
      } : undefined}
      userMenuItems={user ? [
        { label: t('userMenu.preferences'), icon: <UserCog size={14} />, onClick: () => setShowProfile(true) },
        { label: t('userMenu.settings'),    icon: <Settings size={14} />, onClick: () => { window.location.hash = '#/settings'; } },
        { label: t('userMenu.signOut'),     icon: <LogOut size={14} />, onClick: signOut, danger: true },
      ] : []}
      onSignIn={() => { window.location.hash = '#/home'; /* AuthGate handles the flow */ }}
    />
  );

  const palette = showPalette && (
    <CommandPalette
      apps={PALETTE_APPS}
      recentIds={recentApps}
      suites={paletteSuites}
      games={paletteGames}
      actions={paletteActions}
      hasAsk={hasAsk}
      groqKey={groqKey ?? undefined}
      locale={locale}
      initialScope={paletteScope}
      onNavigate={handleNavigate}
      onClose={() => { setShowPalette(false); setPaletteScope(undefined); }}
    />
  );

  const cmdKHint = !showPalette && (
    <CmdKHint t={t} onOpenPalette={() => { setPaletteScope(undefined); setShowPalette(true); }} />
  );

  const profileModal = (
    <ProfileModal
      open={showProfile}
      onClose={() => setShowProfile(false)}
      locale={locale}
    />
  );

  const notifPanel = (
    <NotificationPanel locale={locale} state={notifBell} anchor={notifAnchor} />
  );

  if (activeAppId === 'home') {
    return (
      <ThemeProvider>
        <FadeWrapper key="home">
          <HomeScreen
            apps={APPS}
            recentAppIds={recentApps}
            pinnedAppIds={pinnedApps}
            onTogglePin={handleTogglePin}
            onMovePinned={handleMovePinned}
            onSelect={(app) => { window.location.hash = app.hash; }}
            user={user ? { name: user.user_metadata?.full_name, email: user.email ?? '', avatarUrl: user.user_metadata?.avatar_url } : null}
            onSignOut={signOut}
            onPreferences={() => setShowProfile(true)}
            onOpenPalette={() => { setPaletteScope(undefined); setShowPalette(true); }}
            notifications={{
              count: notifBell.count,
              onClick: handleBellClick,
              label: t('notifications.bell'),
            }}
            suites={{
              entries: visibleSuiteEntries,
              label: t('suites.label'),
              ariaLabel: t('suites.aria'),
              appsLabel: t('suites.appsCount'),
            }}
          />
        </FadeWrapper>
        {palette}
        {cmdKHint}
        {profileModal}
        {notifPanel}
      </ThemeProvider>
    );
  }

  const ActiveRemote = REMOTES[activeAppId];
  const extraProps = EXTRA_PROPS[activeAppId]?.({ user, tmdbKey: TMDB_API_KEY }) ?? {};

  return (
    <ThemeProvider>
      <RemoteErrorBoundary name={activeAppId} topBarRight={topBarRight}>
        <Suspense fallback={<LoadingScreen />}>
          <FadeWrapper key={activeAppId}>
            {ActiveRemote && <ActiveRemote topBarRight={topBarRight} {...extraProps} />}
            {activeAppId === 'settings' && (
              <Layout title="Settings" sidebar={null} topBarRight={topBarRight}>
                <SettingsPage lang={locale === 'pt' ? 'pt' : 'en'} />
              </Layout>
            )}
          </FadeWrapper>
        </Suspense>
      </RemoteErrorBoundary>
      {palette}
      {cmdKHint}
      {profileModal}
      {notifPanel}
    </ThemeProvider>
  );
}
