import type { Locale } from '@atlantis/i18n';
import SHELL_KEYS from '../translations';

const STORAGE_KEY = 'agenda:events';

type AgendaTag = 'personal' | 'team' | 'work';

interface AgendaEvent {
  id: string;
  title: string;
  time: string; // HH:MM
  end?: string; // HH:MM
  tag: AgendaTag;
  done?: boolean;
}

type AgendaStore = Record<string, AgendaEvent[]>;

const TAG_COLORS: Record<AgendaTag, string> = {
  personal: theme.suites.ent,
  team: theme.suites.lab,
  work: theme.suites.learn,
};

const TAG_ORDER: AgendaTag[] = ['personal', 'team', 'work'];

function toMinutes(hhmm: string): number {
  const [h, m] = hhmm.split(':').map((n) => parseInt(n, 10));
  return (Number.isFinite(h) ? h : 0) * 60 + (Number.isFinite(m) ? m : 0);
}

function currentHHMM(): string {
  const d = new Date();
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
}

function sortEvents(list: AgendaEvent[]): AgendaEvent[] {
  return [...list].sort((a, b) => toMinutes(a.time) - toMinutes(b.time));
}

