// ─── Component ───────────────────────────────────────────────────────────────

interface AgendaWidgetProps {
  locale: string;
}

export function AgendaWidget({ locale }: AgendaWidgetProps) {
  const lang: Locale = locale === 'pt' ? 'pt' : 'en';
  const t = useMemo(() => createT(lang, SHELL_KEYS), [lang]);

  const [store, setStore] = useState<AgendaStore>({});
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [draftTitle, setDraftTitle] = useState('');
  const [draftTime, setDraftTime] = useState(() => currentHHMM());
  const [draftEnd, setDraftEnd] = useState('');
  const [draftTag, setDraftTag] = useState<AgendaTag>('personal');
  const [nowMin, setNowMin] = useState(() => {
    const d = new Date();
    return d.getHours() * 60 + d.getMinutes();
  });

  const today = todayISO();
  const events = useMemo(() => sortEvents(store[today] ?? []), [store, today]);

  // Load
  useEffect(() => {
    let cancelled = false;
    (async () => {
      const raw = await getSetting(STORAGE_KEY);
      if (cancelled) return;
      if (raw) {
        try { setStore(JSON.parse(raw) as AgendaStore); } catch { /* ignore */ }
      }
      setLoaded(true);
    })();
    return () => { cancelled = true; };
  }, []);

  // Refresh "now" every minute so past/active states stay accurate.
  useEffect(() => {
    const id = setInterval(() => {
      const d = new Date();
      setNowMin(d.getHours() * 60 + d.getMinutes());
    }, 60_000);
    return () => clearInterval(id);
  }, []);

  const persist = useCallback((next: AgendaStore) => {
    setStore(next);
    putSetting(STORAGE_KEY, JSON.stringify(next));
  }, []);

  const addEvent = useCallback(() => {
    const title = draftTitle.trim();
    if (!title || !/^\d{2}:\d{2}$/.test(draftTime)) return;
    const end = /^\d{2}:\d{2}$/.test(draftEnd) ? draftEnd : undefined;
    const entry: AgendaEvent = {
      id: `e-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
      title,
      time: draftTime,
      end,
      tag: draftTag,
    };
    const next: AgendaStore = {
      ...store,
      [today]: [...(store[today] ?? []), entry],
    };
    persist(next);
    setDraftTitle('');
    setDraftEnd('');
    setDraftTag('personal');
    setDraftTime(currentHHMM());
    setShowForm(false);
  }, [draftTitle, draftTime, draftEnd, draftTag, store, today, persist]);

  const toggleDone = useCallback((id: string) => {
    const list = store[today] ?? [];
    const next: AgendaStore = {
      ...store,
      [today]: list.map((e) => (e.id === id ? { ...e, done: !e.done } : e)),
    };
    persist(next);
  }, [store, today, persist]);

  const removeEvent = useCallback((id: string) => {
    const list = store[today] ?? [];
    const next: AgendaStore = {
      ...store,
      [today]: list.filter((e) => e.id !== id),
    };
    if (next[today].length === 0) delete next[today];
    persist(next);
  }, [store, today, persist]);

  if (!loaded) return null;

  const canSave = draftTitle.trim().length > 0 && /^\d{2}:\d{2}$/.test(draftTime);
  const countLabel = events.length === 1
    ? t('agenda.countOne')
    : t('agenda.count', { n: events.length });

  return (
    <Wrapper>
      <Header>
        <Title>{t('agenda.title')}</Title>
        <Accessory>
          {events.length > 0 && <span>{countLabel}</span>}
          <AddBtn
            type="button"
            active={showForm}
            onClick={() => setShowForm((v) => !v)}
            aria-label={t('agenda.addEvent')}
            title={t('agenda.addEvent')}
          >
            <Icon name="plus" size={12} />
          </AddBtn>
        </Accessory>
      </Header>

      {showForm && (
        <Composer
          onSubmit={(e) => { e.preventDefault(); addEvent(); }}
        >
          <InputRow>
            <Field
              type="time"
              value={draftTime}
              onChange={(e) => setDraftTime(e.target.value)}
              aria-label={t('agenda.timeStart')}
            />
            <Field
              type="text"
              value={draftTitle}
              onChange={(e) => setDraftTitle(e.target.value)}
              placeholder={t('agenda.titlePlaceholder')}
              autoFocus
            />
            <Field
              type="time"
              value={draftEnd}
              onChange={(e) => setDraftEnd(e.target.value)}
              placeholder={t('agenda.timeEnd')}
              aria-label={t('agenda.timeEnd')}
            />
          </InputRow>
          <TagRow>
            {TAG_ORDER.map((tag) => (
              <TagChip
                key={tag}
                type="button"
                color={TAG_COLORS[tag]}
                selected={draftTag === tag}
                onClick={() => setDraftTag(tag)}
              >
                {t(`agenda.tag.${tag}`)}
              </TagChip>
            ))}
          </TagRow>
          <Actions>
            <ActionBtn type="button" onClick={() => setShowForm(false)}>
              {t('agenda.cancel')}
            </ActionBtn>
            <ActionBtn type="submit" primary disabled={!canSave}>
              {t('agenda.save')}
            </ActionBtn>
          </Actions>
        </Composer>
      )}

      {events.length === 0 ? (
        <Empty>
          <div>{t('agenda.empty')}</div>
          {!showForm && (
            <EmptyCta type="button" onClick={() => setShowForm(true)}>
              <Icon name="plus" size={12} />
              {t('agenda.emptyCta')}
            </EmptyCta>
          )}
        </Empty>
      ) : (
        <Timeline>
          <Rail />
          {events.map((ev, i) => {
            const startMin = toMinutes(ev.time);
            const endMin = ev.end ? toMinutes(ev.end) : startMin + 30;
            const isPast = endMin < nowMin && !ev.done ? true : !!ev.done;
            const isActive = !ev.done && startMin <= nowMin && nowMin < endMin;
            const dotColor = ev.done ? theme.colors.mainTextFaint : TAG_COLORS[ev.tag];
            return (
              <Row key={ev.id} delay={i} past={isPast}>
                <TimeCol
                  type="button"
                  active={isActive}
                  past={isPast}
                  onClick={() => toggleDone(ev.id)}
                  aria-label={t('agenda.toggleDone')}
                >
                  {isActive ? t('agenda.now') : ev.time}
                </TimeCol>
                <Body
                  type="button"
                  done={!!ev.done}
                  onClick={() => toggleDone(ev.id)}
                >
                  <Dot color={dotColor} active={isActive} />
                  <div className="title">{ev.title}</div>
                  <div className="meta" style={{ color: TAG_COLORS[ev.tag] }}>
                    {t(`agenda.tag.${ev.tag}`)}
                    {ev.end ? ` · ${ev.time}–${ev.end}` : ` · ${ev.time}`}
                  </div>
                </Body>
                <DeleteBtn
                  type="button"
                  onClick={() => removeEvent(ev.id)}
                  aria-label={t('agenda.delete')}
                  title={t('agenda.delete')}
                >
                  <Icon name="close" size={12} />
                </DeleteBtn>
              </Row>
            );
          })}
        </Timeline>
      )}
    </Wrapper>
  );
}
