import styled from '@emotion/styled';
import { keyframes } from '@emotion/react';
import { theme } from '@atlantis/shared';
import { Eyebrow, Icon, Kbd } from '@atlantis/ui';
import type { IconName } from '@atlantis/ui';
import type { TFunction } from '@atlantis/i18n';

const fadeUp = keyframes`
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
`;

const Card = styled.div`
  position: relative;
  padding: ${theme.spacing.xl};
  background: ${theme.colors.surface};
  border: 1px solid ${theme.colors.border};
  border-radius: ${theme.borderRadius.lg};
  display: flex;
  flex-direction: column;
  gap: ${theme.spacing.md};
  margin-bottom: ${theme.spacing.lg};
  animation: ${fadeUp} 0.25s ${theme.transitions.easing} both;

  &::before {
    content: '';
    position: absolute;
    left: 0;
    top: 12px;
    bottom: 12px;
    width: 2px;
    background: ${theme.colors.accent};
    border-radius: 0 2px 2px 0;
  }
`;

const HeaderRow = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: ${theme.spacing.md};
`;

const TitleCol = styled.div`
  display: flex;
  flex-direction: column;
  gap: 4px;
`;

const Title = styled.div`
  font-family: ${theme.typography.fontFamilySerif};
  font-size: ${theme.typography.fontSizeLg};
  font-weight: 400;
  color: ${theme.colors.mainText};
`;

const Subtitle = styled.div`
  font-family: ${theme.typography.fontFamily};
  font-size: ${theme.typography.fontSizeBase};
  color: ${theme.colors.mainTextMuted};
  line-height: 1.5;
  max-width: 560px;
`;

const DismissBtn = styled.button`
  flex-shrink: 0;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  border: 1px solid ${theme.colors.border};
  background: transparent;
  color: ${theme.colors.mainTextMuted};
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition:
    color ${theme.transitions.fast},
    border-color ${theme.transitions.fast};

  &:hover {
    color: ${theme.colors.mainText};
    border-color: ${theme.colors.mainText};
  }
  &:focus-visible { ${theme.focusRing} }
`;

const TipsGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: ${theme.spacing.md};

  @media (max-width: ${theme.breakpoints.md}) {
    grid-template-columns: 1fr;
  }
`;

const TipCard = styled.button`
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: ${theme.spacing.md};
  background: ${theme.colors.mainBg};
  border: 1px solid ${theme.colors.borderSubtle};
  border-radius: ${theme.borderRadius.md};
  text-align: left;
  cursor: pointer;
  transition:
    border-color ${theme.transitions.fast},
    transform ${theme.transitions.fast};

  &:hover {
    border-color: ${theme.colors.accent};
    transform: translateY(-1px);
  }
  &:focus-visible { ${theme.focusRing} }
`;

const TipIcon = styled.div`
  color: ${theme.colors.accent};
`;

const TipTitle = styled.div`
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: ${theme.typography.fontFamily};
  font-size: ${theme.typography.fontSizeBase};
  font-weight: 600;
  color: ${theme.colors.mainText};
`;

const TipBody = styled.div`
  font-family: ${theme.typography.fontFamily};
  font-size: ${theme.typography.fontSizeSm};
  color: ${theme.colors.mainTextMuted};
  line-height: 1.45;
`;

interface OnboardingTip {
  iconName: IconName;
  titleKey: string;
  bodyKey: string;
  kbd?: string;
  onClick?: () => void;
}

interface OnboardingCardProps {
  t: TFunction;
  onDismiss: () => void;
  onOpenPalette?: () => void;
  onOpenPreferences?: () => void;
}

export function OnboardingCard({ t, onDismiss, onOpenPalette, onOpenPreferences }: OnboardingCardProps) {
  const tips: OnboardingTip[] = [
    {
      iconName: 'search',
      titleKey: 'onboarding.tip.palette.title',
      bodyKey: 'onboarding.tip.palette.body',
      kbd: '⌘K',
      onClick: onOpenPalette,
    },
    {
      iconName: 'settings',
      titleKey: 'onboarding.tip.preferences.title',
      bodyKey: 'onboarding.tip.preferences.body',
      onClick: onOpenPreferences,
    },
    {
      iconName: 'check',
      titleKey: 'onboarding.tip.daily.title',
      bodyKey: 'onboarding.tip.daily.body',
      onClick: () => { window.location.hash = '#/daily'; },
    },
  ];

  return (
    <Card role="region" aria-label={t('onboarding.aria')}>
      <HeaderRow>
        <TitleCol>
          <Eyebrow>{t('onboarding.eyebrow')}</Eyebrow>
          <Title>{t('onboarding.title')}</Title>
          <Subtitle>{t('onboarding.subtitle')}</Subtitle>
        </TitleCol>
        <DismissBtn
          type="button"
          title={t('onboarding.dismiss')}
          aria-label={t('onboarding.dismiss')}
          onClick={onDismiss}
        >
          <Icon name="close" size={14} />
        </DismissBtn>
      </HeaderRow>

      <TipsGrid>
        {tips.map((tip) => (
          <TipCard
            key={tip.titleKey}
            type="button"
            onClick={tip.onClick}
            disabled={!tip.onClick}
          >
            <TipIcon aria-hidden>
              <Icon name={tip.iconName} size={18} />
            </TipIcon>
            <TipTitle>
              {t(tip.titleKey)}
              {tip.kbd && <Kbd>{tip.kbd}</Kbd>}
            </TipTitle>
            <TipBody>{t(tip.bodyKey)}</TipBody>
          </TipCard>
        ))}
      </TipsGrid>
    </Card>
  );
}
