/**
 * Central configuration for all apps.
 *
 * Source of truth: `apps.config.yml`. Edit that file to add/remove apps or
 * change their properties. Set `enabled: false` to hide an app, or use
 * `flag: '<name>'` to defer to a feature flag (see `flags.ts`).
 *
 * Every user-visible string goes through `@atlantis/i18n` — `labelKey` and
 * `descriptionKey` are translation keys, not display text. Add the actual
 * copy to `translations.ts` under `apps.<id>.label` / `apps.<id>.description`.
 */
import appsData from './apps.config.yml';
import type { Interest } from '@atlantis/shared';

/** Where an app shows up in the shell. */
export type Visibility =
  /** Home grid + palette + suite-browse. */
  | 'default'
  /** Palette + suite-browse only. Same as legacy `homeHidden: true`. */
  | 'hidden-home'
  /** Palette only — drops out of home and suite-browse. */
  | 'search-only'
  /** Nowhere. Use for apps that are registered but user-facing gated by a
   *  flag; often paired with `flag: '<name>'` (see `flags.ts`). */
  | 'hidden';

export interface AppConfig {
  id: string;
  port: number;
  /** Translation key (e.g. 'apps.games.label'). Resolve with `t(config.labelKey)`. */
  labelKey: string;
  /** Translation key (e.g. 'apps.games.description'). Resolve with `t(config.descriptionKey)`. */
  descriptionKey: string;
  /** Primary hash route, e.g. '#/games'. */
  hash: string;
  /** Extra hash prefixes that route to this app (e.g. 'lebem' → games). Primary hash is NOT duplicated here. */
  hashAliases?: string[];
  icon: string;
  color: string;
  enabled: boolean;
  /** Optional feature-flag name. When set, the flag resolver (see
   *  `flags.ts`) overrides `enabled`. `true` keeps the app visible; `false`
   *  hides it. Missing flag name → resolver returns `false`. */
  flag?: string;
  category: string;
  needsAuth: boolean;
  suite?: string;
  /** @deprecated Use `visibility: 'hidden-home'` instead. Kept for
   *  back-compat; `visibilityOf()` prefers `visibility` when both are set. */
  homeHidden?: boolean;
  /** Where the app appears. Defaults to `'default'`. See `Visibility`. */
  visibility?: Visibility;
  /** If set, the app is hidden when `hasInterests(profile)` is true and
   *  `profile.interests` doesn't include this tag. Apps without `interest`
   *  (tools, utilities) are always shown regardless of selected interests.
   *
   *  Note: `profile.ageMode` is NOT used to hide apps — apps that need to
   *  respect age mode must adjust their own content internally. */
  interest?: Interest;
}

/** Resolves an app's visibility, honouring back-compat with `homeHidden`.
 *  The legacy field is read via a bracket access so TS' `@deprecated`
 *  hint doesn't fire inside the bridge that exists exactly for it. */
export function visibilityOf(app: AppConfig): Visibility {
  if (app.visibility) return app.visibility;
  const legacy = (app as { homeHidden?: boolean }).homeHidden;
  if (legacy) return 'hidden-home';
  return 'default';
}

// yaml-loader emits `unknown`; we assert through `AppConfig[]`. Shape is
// validated at review time, and `normalize()` in profile.ts would reject
// bad `interest` values at runtime.
const APPS: AppConfig[] = appsData as AppConfig[];

export default APPS;
