// ── Styled ────────────────────────────────────────────────────────────────────

const fadeIn = keyframes`
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: translateY(0); }
`;

const twinkle = keyframes`
  0%, 100% { opacity: 0.85; }
  50%      { opacity: 0.55; }
`;

const Wrapper = styled.div`
  display: flex;
  flex-direction: column;
  gap: 10px;
  height: 100%;
  animation: ${fadeIn} 0.3s ease both;
`;

const Header = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: ${theme.spacing.sm};
`;

const Title = styled.div`
  font-size: 11px;
  font-weight: 600;
  font-family: ${theme.typography.fontFamilyMono};
  color: ${theme.colors.mainTextMuted};
  letter-spacing: 0.06em;
  text-transform: uppercase;
`;

const Accessory = styled.div`
  font-size: 10px;
  font-family: ${theme.typography.fontFamilyMono};
  color: ${theme.colors.mainTextFaint};
  letter-spacing: 0.04em;
`;

const SkyFrame = styled.div`
  position: relative;
  flex: 1;
  min-height: 0;
  background:
    radial-gradient(ellipse at center, #0b1630 0%, #05080f 70%);
  border: 1px solid ${theme.colors.borderSubtle};
  border-radius: ${theme.borderRadius.md};
  overflow: hidden;
`;

const Legend = styled.div`
  font-family: ${theme.typography.fontFamilyMono};
  font-size: 10px;
  color: ${theme.colors.mainTextFaint};
  letter-spacing: 0.04em;
  text-align: center;
`;

const StarDot = styled.circle`
  animation: ${twinkle} 3s ease-in-out infinite;
`;

const Daytime = styled.div`
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: ${theme.spacing.md};
  color: ${theme.colors.mainTextMuted};
  font-family: ${theme.typography.fontFamilyMono};
  font-size: 11px;
  letter-spacing: 0.08em;
`;

function isNight(): boolean {
  const h = new Date().getHours();
  return h >= 20 || h < 7;
}

interface NightSkyWidgetProps {
  locale: string;
}

export function NightSkyWidget({ locale }: NightSkyWidgetProps) {
  const lang: Locale = locale === 'pt' ? 'pt' : 'en';
  const t = useMemo<TFunction>(() => createT(lang, SHELL_KEYS), [lang]);

  const [now, setNow] = useState<Date>(new Date());

  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 60_000);
    return () => clearInterval(id);
  }, []);

  const night = isNight();
  const rotation = ((now.getHours() * 60 + now.getMinutes()) / (24 * 60)) * 360;
  const size = 260;
  const cx = size / 2;
  const cy = size / 2;
  const radius = size / 2 - 8;

  return (
    <Wrapper>
      <Header>
        <Title>{t('nightSky.title')}</Title>
        <Accessory>{t('astro.location')}</Accessory>
      </Header>

      <SkyFrame>
        {night ? (
          <svg
            width="100%"
            height="100%"
            viewBox={`0 0 ${size} ${size}`}
            preserveAspectRatio="xMidYMid meet"
          >
            {/* Horizon ring */}
            <circle
              cx={cx}
              cy={cy}
              r={radius}
              fill="none"
              stroke={theme.colors.borderSubtle}
              strokeWidth="1"
              strokeDasharray="2 4"
              opacity="0.45"
            />
            {/* Cardinal ticks */}
            {[0, 90, 180, 270].map((deg) => {
              const rad = (deg * Math.PI) / 180;
              const x1 = cx + Math.cos(rad) * radius;
              const y1 = cy + Math.sin(rad) * radius;
              const x2 = cx + Math.cos(rad) * (radius - 6);
              const y2 = cy + Math.sin(rad) * (radius - 6);
              return (
                <line
                  key={deg}
                  x1={x1}
                  y1={y1}
                  x2={x2}
                  y2={y2}
                  stroke={theme.colors.mainTextFaint}
                  strokeWidth="1"
                  opacity="0.4"
                />
              );
            })}

            {/* Constellations — rotate slowly with time */}
            <g transform={`rotate(${rotation} ${cx} ${cy})`}>
              {CONSTELLATIONS.map((con) => {
                const stars = con.stars.map((s) => ({
                  cx: 16 + s.x * (size - 32),
                  cy: 16 + s.y * (size - 32),
                  r: Math.max(0.8, 2.6 - s.mag * 0.6),
                }));
                return (
                  <g key={con.id}>
                    {con.lines.map(([a, b], i) => (
                      <line
                        key={i}
                        x1={stars[a].cx}
                        y1={stars[a].cy}
                        x2={stars[b].cx}
                        y2={stars[b].cy}
                        stroke="rgba(139,123,255,0.25)"
                        strokeWidth="0.6"
                      />
                    ))}
                    {stars.map((s, i) => (
                      <StarDot
                        key={i}
                        cx={s.cx}
                        cy={s.cy}
                        r={s.r}
                        fill="#f2ecd8"
                        style={{ animationDelay: `${(i % 6) * 0.4}s` }}
                      />
                    ))}
                  </g>
                );
              })}
            </g>
          </svg>
        ) : (
          <Daytime>{t('nightSky.dayTitle')}</Daytime>
        )}
      </SkyFrame>

      {night && (
        <Legend>
          {t('nightSky.nightLegend', { count: CONSTELLATIONS.length })}
        </Legend>
      )}
    </Wrapper>
  );
}
