/**
 * Lightweight Groq chat helper.
 *
 * Key resolution order:
 *   1. User-set key in `atlantis:api-keys` (managed by SettingsPage).
 *   2. Optional build-time `process.env.GROK_API_KEY` when injected by the host.
 *
 * Returns `null` when no key is configured — callers should hide
 * the Ask affordance entirely in that case.
 */

import { getSetting } from './db';

// Some hosts inject process.env at build time while others run browser-only.
// Keep this declaration local and guard accesses with typeof checks.
declare const process: { env: { GROK_API_KEY?: string } };

interface ApiKeysSetting {
  groq?: string;
  gemini?: string;
}

const SETTINGS_KEY = 'atlantis:api-keys';
const LEGACY_SETTINGS_KEY = 'atlantis:promptlab:keys';
const ENDPOINT = 'https://api.groq.com/openai/v1/chat/completions';
const MODEL = 'llama-3.1-8b-instant';

/**
 * Models exposed to the Ask UI's settings popover. Keep this aligned with
 * Groq's currently-supported chat-completion models. The `id` is sent in
 * the request body verbatim; labels are user-facing.
 */
export interface GroqModel {
  id: string;
  label: string;
  /** One-line description for the settings select. */
  hint: string;
}

export const GROQ_MODELS: GroqModel[] = [
  {
    id: 'llama-3.1-8b-instant',
    label: 'Llama 3.1 · 8B · instant',
    hint: 'Fast default — good for short answers',
  },
  {
    id: 'llama-3.3-70b-versatile',
    label: 'Llama 3.3 · 70B · versatile',
    hint: 'Slower but stronger reasoning',
  },
  {
    id: 'openai/gpt-oss-120b',
    label: 'GPT-OSS · 120B',
    hint: 'Largest open-weights option',
  },
];

export const DEFAULT_GROQ_MODEL_ID = MODEL;

function getEnvGroqKey(): string | null {
  if (typeof process === 'undefined') return null;
  const envKey = process.env?.GROK_API_KEY;
  if (!envKey || envKey.length === 0) return null;
  return envKey;
}

function getLocalStorageGroqKey(): string | null {
  if (typeof localStorage === 'undefined') return null;
  try {
    const current = localStorage.getItem(SETTINGS_KEY);
    if (current) {
      const parsed = JSON.parse(current) as ApiKeysSetting;
      if (parsed.groq && parsed.groq.length > 0) return parsed.groq;
    }

    const legacy = localStorage.getItem(LEGACY_SETTINGS_KEY);
    if (legacy) {
      const parsed = JSON.parse(legacy) as ApiKeysSetting;
      if (parsed.groq && parsed.groq.length > 0) return parsed.groq;
    }
  } catch {
    /* ignore parse/storage errors */
  }
  return null;
}

export async function resolveGroqKey(): Promise<string | null> {
  try {
    const raw = await getSetting(SETTINGS_KEY);
    if (raw) {
      const parsed: ApiKeysSetting = JSON.parse(raw);
      if (parsed.groq && parsed.groq.length > 0) return parsed.groq;
    }
  } catch {
    /* corrupt or missing */
  }
  const localKey = getLocalStorageGroqKey();
  if (localKey) return localKey;
  return getEnvGroqKey();
}

export function hasEnvGroqKey(): boolean {
  return getEnvGroqKey() !== null;
}

interface GroqResponse {
  choices?: Array<{ message?: { content?: string } }>;
  error?: { message?: string };
}

export interface GroqMessage {
  role: 'user' | 'assistant';
  content: string;
}

export interface GroqAskOptions {
  key: string;
  system?: string;
  locale?: 'en' | 'pt';
  signal?: AbortSignal;
  /** Previous conversation turns (up to last 6) sent as context. */
  history?: GroqMessage[];
  /** Maximum tokens in the response. Default: 1024. */
  maxTokens?: number;
}

export interface GroqStreamOptions extends GroqAskOptions {
  /**
   * Called with the cumulative answer text on every received SSE chunk.
   * Use it to update the UI progressively. The same final string is also
   * returned by the promise once the stream completes.
   */
  onChunk?: (textSoFar: string) => void;
}

export async function askGroq(
  prompt: string,
  options: GroqAskOptions,
): Promise<string> {
  const lang = options.locale === 'pt' ? 'Portuguese' : 'English';
  const system =
    options.system ??
    [
      `You are Atlantis, a concise personal-dashboard assistant.`,
      `Answer in ${lang}. Stay focused and reasonably concise.`,
      `If you don't know, say so plainly.`,
      ``,
      `Responses render as rich Markdown in the Atlantis UI. Use these blocks when`,
      `they fit the answer:`,
      `- Headings, bold/italic, bullet & numbered lists, GFM tables and task lists.`,
      `- Fenced code blocks with a language tag (\`\`\`ts / \`\`\`py / \`\`\`sql …).`,
      `- Callouts as blockquotes: \`> [!NOTE]\`, \`> [!TIP]\`, \`> [!IMPORTANT]\`,`,
      `  \`> [!WARNING]\`, \`> [!CAUTION]\`.`,
      `- Mermaid diagrams: fenced \`\`\`mermaid block (Mermaid 11 syntax).`,
      `  The FIRST non-empty line MUST declare one of these diagram types,`,
      `  otherwise the block will not render:`,
      `    graph | flowchart | sequenceDiagram | classDiagram |`,
      `    stateDiagram | stateDiagram-v2 | erDiagram | pie | gantt |`,
      `    journey | mindmap | gitGraph | sankey-beta | quadrantChart |`,
      `    requirementDiagram | timeline | xychart-beta | block-beta |`,
      `    C4Context | C4Container | C4Component | C4Dynamic | C4Deployment.`,
      `  Example first line: \`graph TD\` or \`flowchart LR\` or \`sequenceDiagram\`.`,
      `- Numeric charts: fenced \`\`\`chart block. Only \`type: bar\`, \`type: pie\`,`,
      `  and \`type: line\` are supported. Body keys: \`labels: [..]\`, \`data: [..]\`,`,
      `  optional \`title:\` and \`colors:\`. Any other chart type will not render.`,
      ``,
      `Default to Mermaid for relationships/flows and \`chart\` for quantitative`,
      `data the user provided. Never use Mermaid for time-series or numeric`,
      `trends (value per year / month / category) — those are always \`chart\`.`,
      `Never emit an empty fenced block. Never emit a mermaid block without a`,
      `diagram-type declaration on its first line. Keep caption text short`,
      `around rendered blocks.`,
    ].join('\n');

  // Cap history at last 6 turns to keep request size small.
  const historyMessages = (options.history ?? []).slice(-6);

  const res = await fetch(ENDPOINT, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${options.key}`,
    },
    body: JSON.stringify({
      model: MODEL,
      messages: [
        { role: 'system', content: system },
        ...historyMessages,
        { role: 'user', content: prompt },
      ],
      temperature: 0.4,
      max_tokens: options.maxTokens ?? 1024,
    }),
    signal: options.signal,
  });

  const data = (await res.json()) as GroqResponse;
  if (!res.ok) {
    throw new Error(data.error?.message ?? `Groq HTTP ${res.status}`);
  }
  const text = data.choices?.[0]?.message?.content?.trim();
  if (!text) throw new Error('Empty response from Groq');
  return text;
}

interface GroqStreamChunk {
  choices?: Array<{ delta?: { content?: string } }>;
}

/**
 * Streaming variant of {@link askGroq}. Same options + an `onChunk` callback
 * that fires on every SSE delta with the accumulated answer text. The
 * returned promise resolves to the final full text once the stream closes.
 *
 * Build the system prompt at the call site (same shape as askGroq) — when
 * `system` is omitted this falls back to the same default markdown contract.
 */
export async function askGroqStream(
  prompt: string,
  options: GroqStreamOptions,
): Promise<string> {
  const lang = options.locale === 'pt' ? 'Portuguese' : 'English';
  const system =
    options.system ??
    [
      `You are Atlantis, a concise personal-dashboard assistant.`,
      `Answer in ${lang}. Stay focused and reasonably concise.`,
      `If you don't know, say so plainly.`,
    ].join('\n');

  const historyMessages = (options.history ?? []).slice(-6);

  const res = await fetch(ENDPOINT, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${options.key}`,
    },
    body: JSON.stringify({
      model: MODEL,
      messages: [
        { role: 'system', content: system },
        ...historyMessages,
        { role: 'user', content: prompt },
      ],
      temperature: 0.4,
      max_tokens: options.maxTokens ?? 1024,
      stream: true,
    }),
    signal: options.signal,
  });

  if (!res.ok) {
    let errMsg = `Groq HTTP ${res.status}`;
    try {
      const data = (await res.json()) as GroqResponse;
      if (data.error?.message) errMsg = data.error.message;
    } catch {
      /* response wasn't JSON — keep the HTTP status */
    }
    throw new Error(errMsg);
  }
  if (!res.body) throw new Error('Empty response body from Groq');

  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let acc = '';

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });

      // SSE frames are separated by blank lines. Process every complete
      // frame; keep the trailing partial frame in the buffer for next read.
      const frames = buffer.split('\n\n');
      buffer = frames.pop() ?? '';

      for (const frame of frames) {
        // A frame can have multiple `data:` lines; concatenate per spec.
        const data = frame
          .split('\n')
          .filter((line) => line.startsWith('data:'))
          .map((line) => line.slice(5).trimStart())
          .join('');
        if (!data) continue;
        if (data === '[DONE]') {
          if (!acc.trim()) throw new Error('Empty response from Groq');
          return acc.trim();
        }
        try {
          const json = JSON.parse(data) as GroqStreamChunk;
          const delta = json.choices?.[0]?.delta?.content;
          if (typeof delta === 'string' && delta.length > 0) {
            acc += delta;
            options.onChunk?.(acc);
          }
        } catch {
          /* malformed frame — Groq sometimes emits keepalives, skip */
        }
      }
    }
  } finally {
    try { reader.releaseLock(); } catch { /* ignore */ }
  }

  if (!acc.trim()) throw new Error('Empty response from Groq');
  return acc.trim();
}
