const STORAGE_KEY = 'reading:state';

interface CurrentBook {
  title: string;
  author: string;
  page: number;
  pages: number;
  startedAt: number;
}

interface FinishedBook {
  title: string;
  author: string;
  pages: number;
  finishedAt: number;
}

interface ReadingState {
  current: CurrentBook | null;
  finished: FinishedBook[];
  goal: number;
}

const DEFAULT_GOAL = 24;
const DEFAULT_STATE: ReadingState = { current: null, finished: [], goal: DEFAULT_GOAL };

function booksThisYear(finished: FinishedBook[]): number {
  const year = new Date().getFullYear();
  return finished.filter((b) => new Date(b.finishedAt).getFullYear() === year).length;
}

function pagesThisWeek(current: CurrentBook | null): number {
  if (!current) return 0;
  const started = current.startedAt;
  const daysSince = Math.max(1, Math.ceil((Date.now() - started) / 86_400_000));
  const pagesRead = Math.min(current.page, current.pages);
  const perDay = pagesRead / daysSince;
  return Math.round(perDay * 7);
}

function pagesPerDay(current: CurrentBook | null): number {
  if (!current) return 0;
  const daysSince = Math.max(1, Math.ceil((Date.now() - current.startedAt) / 86_400_000));
  return Math.round(current.page / daysSince);
}

