interface ReadingWidgetProps {
  locale: string;
}

export function ReadingWidget({ locale }: ReadingWidgetProps) {
  const lang: Locale = locale === 'pt' ? 'pt' : 'en';
  const t = useMemo(() => createT(lang, SHELL_KEYS), [lang]);

  const [state, setState] = useState<ReadingState>(DEFAULT_STATE);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [draftTitle, setDraftTitle] = useState('');
  const [draftAuthor, setDraftAuthor] = useState('');
  const [draftPage, setDraftPage] = useState('');
  const [draftPages, setDraftPages] = useState('');
  const [draftGoal, setDraftGoal] = useState(String(DEFAULT_GOAL));

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const raw = await getSetting(STORAGE_KEY);
      if (cancelled) return;
      if (raw) {
        try {
          const parsed = JSON.parse(raw) as ReadingState;
          setState({
            current: parsed.current ?? null,
            finished: Array.isArray(parsed.finished) ? parsed.finished : [],
            goal: typeof parsed.goal === 'number' && parsed.goal > 0 ? parsed.goal : DEFAULT_GOAL,
          });
        } catch { /* ignore */ }
      }
      setLoaded(true);
    })();
    return () => { cancelled = true; };
  }, []);

  const persist = useCallback((next: ReadingState) => {
    setState(next);
    putSetting(STORAGE_KEY, JSON.stringify(next));
  }, []);

  const openEditor = useCallback(() => {
    if (state.current) {
      setDraftTitle(state.current.title);
      setDraftAuthor(state.current.author);
      setDraftPage(String(state.current.page));
      setDraftPages(String(state.current.pages));
    } else {
      setDraftTitle('');
      setDraftAuthor('');
      setDraftPage('');
      setDraftPages('');
    }
    setDraftGoal(String(state.goal));
    setShowForm(true);
  }, [state]);

  const save = useCallback(() => {
    const title = draftTitle.trim();
    const author = draftAuthor.trim();
    const pages = parseInt(draftPages, 10);
    const page = parseInt(draftPage, 10);
    const goal = parseInt(draftGoal, 10) || DEFAULT_GOAL;
    if (!title || !author || !Number.isFinite(pages) || pages <= 0) return;
    const safePage = Number.isFinite(page) ? Math.max(0, Math.min(pages, page)) : 0;
    const startedAt = state.current && state.current.title === title && state.current.author === author
      ? state.current.startedAt
      : Date.now();
    const next: ReadingState = {
      ...state,
      current: { title, author, page: safePage, pages, startedAt },
      goal,
    };
    persist(next);
    setShowForm(false);
  }, [draftTitle, draftAuthor, draftPage, draftPages, draftGoal, state, persist]);

  const finishCurrent = useCallback(() => {
    if (!state.current) return;
    const finished: FinishedBook = {
      title: state.current.title,
      author: state.current.author,
      pages: state.current.pages,
      finishedAt: Date.now(),
    };
    const next: ReadingState = {
      ...state,
      current: null,
      finished: [finished, ...state.finished],
    };
    persist(next);
    setShowForm(false);
  }, [state, persist]);

  if (!loaded) return null;

  const { current, finished, goal } = state;
  const read = booksThisYear(finished);
  const pct = current ? Math.max(0, Math.min(100, Math.round((current.page / current.pages) * 100))) : 0;
  const canSave = draftTitle.trim().length > 0
    && draftAuthor.trim().length > 0
    && /^\d+$/.test(draftPages.trim())
    && parseInt(draftPages, 10) > 0;

  return (
    <Wrapper>
      <Header>
        <Title>{t('reading.title')}</Title>
        <Accessory>
          <span>{t('reading.yearProgress', { read, goal })}</span>
          <EditBtn
            type="button"
            onClick={openEditor}
            aria-label={current ? t('reading.updateBook') : t('reading.addBook')}
            title={current ? t('reading.updateBook') : t('reading.addBook')}
          >
            <Icon name={current ? 'settings' : 'plus'} size={12} />
          </EditBtn>
        </Accessory>
      </Header>

      {showForm && (
        <Composer onSubmit={(e) => { e.preventDefault(); save(); }}>
          <Field
            type="text"
            value={draftTitle}
            onChange={(e) => setDraftTitle(e.target.value)}
            placeholder={t('reading.placeholder.title')}
            autoFocus
          />
          <Field
            type="text"
            value={draftAuthor}
            onChange={(e) => setDraftAuthor(e.target.value)}
            placeholder={t('reading.placeholder.author')}
          />
          <PagesRow>
            <Field
              type="number"
              value={draftPage}
              onChange={(e) => setDraftPage(e.target.value)}
              placeholder={t('reading.placeholder.page')}
              min={0}
            />
            <Field
              type="number"
              value={draftPages}
              onChange={(e) => setDraftPages(e.target.value)}
              placeholder={t('reading.placeholder.pages')}
              min={1}
            />
            <Field
              type="number"
              value={draftGoal}
              onChange={(e) => setDraftGoal(e.target.value)}
              placeholder={t('reading.placeholder.goal')}
              min={1}
              aria-label={t('reading.goal')}
            />
          </PagesRow>
          <Actions>
            {current ? (
              <ActionBtn type="button" danger onClick={finishCurrent}>
                {t('reading.finish')}
              </ActionBtn>
            ) : <span />}
            <div style={{ display: 'flex', gap: 6 }}>
              <SecondaryBtn type="button" onClick={() => setShowForm(false)}>
                {t('reading.cancel')}
              </SecondaryBtn>
              <ActionBtn type="submit" primary disabled={!canSave}>
                {t('reading.save')}
              </ActionBtn>
            </div>
          </Actions>
        </Composer>
      )}

      {current ? (
        <Body>
          <CurrentRow>
            <Cover>CAPA</Cover>
            <BookMeta>
              <div>
                <BookTitle>{current.title}</BookTitle>
                <BookAuthor>{current.author}</BookAuthor>
              </div>
              <ProgressWrap>
                <ProgressMeta>
                  <span>
                    {t('reading.page')} {current.page} / {current.pages}
                  </span>
                  <ProgressPct>{pct}%</ProgressPct>
                </ProgressMeta>
                <ProgressTrack>
                  <ProgressFill pct={pct} />
                </ProgressTrack>
              </ProgressWrap>
            </BookMeta>
          </CurrentRow>

          <YearSection>
            <YearLabel>
              <span>{t('reading.yearGoal')}</span>
              <span>{read}/{goal} {t('reading.books')}</span>
            </YearLabel>
            <YearGrid goal={goal}>
              {Array.from({ length: goal }).map((_, i) => (
                <YearCell key={i} filled={i < read} />
              ))}
            </YearGrid>
          </YearSection>

          <StatsRow>
            <Stat>
              <StatLabel>{t('reading.stat.week')}</StatLabel>
              <StatValue>
                {pagesThisWeek(current)}
                <StatUnit>{t('reading.unit.pages')}</StatUnit>
              </StatValue>
            </Stat>
            <Stat>
              <StatLabel>{t('reading.stat.pace')}</StatLabel>
              <StatValue>
                {pagesPerDay(current)}
                <StatUnit>{t('reading.unit.perDay')}</StatUnit>
              </StatValue>
            </Stat>
            <Stat>
              <StatLabel>{t('reading.stat.finished')}</StatLabel>
              <StatValue>
                {finished.length}
                <StatUnit>{t('reading.unit.total')}</StatUnit>
              </StatValue>
            </Stat>
          </StatsRow>
        </Body>
      ) : (
        <Empty>
          <div>{t('reading.empty')}</div>
          {!showForm && (
            <EmptyCta type="button" onClick={openEditor}>
              <Icon name="plus" size={12} />
              {t('reading.addBook')}
            </EmptyCta>
          )}
        </Empty>
      )}
    </Wrapper>
  );
}
