import { useEffect, useRef, useState } from 'react';
import styled from '@emotion/styled';
import { theme } from '@atlantis/shared';

const Wrapper = styled.div`
  background: ${theme.colors.codeBg};
  border: 1px solid ${theme.colors.codeBorder};
  border-radius: ${theme.borderRadius.md};
  padding: ${theme.spacing.lg};
  margin: ${theme.spacing.lg} 0;
  overflow-x: auto;
  text-align: center;
  svg { max-width: 100%; }
`;

const Fallback = styled.pre`
  background: ${theme.colors.codeBg};
  border: 1px solid ${theme.colors.codeBorder};
  border-radius: ${theme.borderRadius.md};
  padding: ${theme.spacing.md};
  margin: ${theme.spacing.lg} 0;
  overflow-x: auto;
  font-family: ${theme.typography.fontFamilyMono};
  font-size: 12.5px;
  color: ${theme.colors.mainTextMuted};
  white-space: pre-wrap;
`;

let mermaidInitialized = false;

/**
 * Resolve a `var(--foo)` reference against `document.documentElement`.
 * Returns the input untouched when it isn't a CSS custom property (plain
 * hex / rgb / named colours pass straight through) or when the variable
 * can't be resolved (fall back to the raw string — worse than a real
 * colour, but at least deterministic).
 */
function resolveCssColor(raw: string): string {
  if (typeof window === 'undefined') return raw;
  const m = raw.match(/^var\((--[-\w]+)\)$/);
  if (!m) return raw;
  const resolved = getComputedStyle(document.documentElement)
    .getPropertyValue(m[1])
    .trim();
  return resolved || raw;
}

export function MermaidBlock({ code }: { code: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [empty, setEmpty] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setError(null);
    setEmpty(false);

    // Skip wholly-empty input so we don't leave a ghost wrapper on the page.
    if (!code.trim()) {
      setEmpty(true);
      return;
    }

    // LLMs sometimes emit content inside a ```mermaid fence that isn't a
    // real Mermaid diagram — mermaid.render then succeeds but returns an
    // SVG with near-zero geometry. Short-circuit before we even try, by
    // checking the first non-empty line declares a known diagram type.
    const VALID_TYPES = /^(?:---[\s\S]*?---\s*)?(?:graph|flowchart|sequenceDiagram|classDiagram|stateDiagram(?:-v2)?|erDiagram|pie|gantt|journey|mindmap|gitGraph|sankey(?:-beta)?|quadrantChart|requirementDiagram|timeline|xychart-beta|block-beta|C4Context|C4Container|C4Component|C4Dynamic|C4Deployment)\b/;
    const firstMeaningful = code.trim().split(/\r?\n/)[0]?.trim() ?? '';
    if (!VALID_TYPES.test(firstMeaningful)) {
      setEmpty(true);
      return;
    }

    async function render() {
      const mermaid = (await import('mermaid')).default;
      if (!mermaidInitialized) {
        // Mermaid's colour parser rejects CSS custom properties
        // (`var(--at-accent)`) and logs "Unsupported color format".
        // Resolve our theme tokens to their concrete hex/rgb values at
        // init time so mermaid only ever sees real colours.
        mermaid.initialize({
          startOnLoad: false,
          theme: 'dark',
          themeVariables: {
            background: resolveCssColor(theme.colors.codeBg),
            primaryColor: resolveCssColor(theme.colors.accent),
            primaryTextColor: resolveCssColor(theme.colors.mainText),
            lineColor: resolveCssColor(theme.colors.border),
          },
        });
        mermaidInitialized = true;
      }
      if (!ref.current || cancelled) return;
      try {
        const id = `mermaid-${Math.random().toString(36).slice(2)}`;
        const { svg } = await mermaid.render(id, code);
        if (cancelled || !ref.current) return;

        // Mermaid 11 doesn't always throw on syntax errors — it can resolve
        // with a "bomb" SVG that says "Syntax error in text". Detect that
        // and fall back to the raw source instead of injecting it.
        if (/aria-roledescription="error"|class="error-icon"|>Syntax error/i.test(svg)) {
          setEmpty(true);
          return;
        }

        ref.current.innerHTML = svg;

        // Belt-and-braces: after layout, if the rendered SVG has effectively
        // zero geometry (mermaid "succeeded" with an empty diagram), fall
        // back to the raw source instead of leaving a ghost bordered box.
        requestAnimationFrame(() => {
          if (cancelled || !ref.current) return;
          const svgEl = ref.current.querySelector('svg');
          if (!svgEl) {
            setEmpty(true);
            return;
          }
          const bb = svgEl.getBoundingClientRect();
          if (bb.width < 40 || bb.height < 40) {
            setEmpty(true);
          }
        });
      } catch (err) {
        if (!cancelled) setError(err instanceof Error ? err.message : String(err));
      }
    }
    render();
    return () => { cancelled = true; };
  }, [code]);

  if (error || empty) return <Fallback>{code.trim()}</Fallback>;
  return <Wrapper ref={ref} />;
}

export default MermaidBlock;
