import { theme } from '@atlantis/shared';
import { createT } from '@atlantis/i18n';
import type { Locale, TFunction } from '@atlantis/i18n';
import SHELL_KEYS from '../translations';
import { cachedFetch } from './cachedFetch';

const LAT = 38.72;
const LON = -9.14;
const CACHE_KEY_PREFIX = 'astro-sun-';

interface SunData {
  sunriseUtc: string; // ISO
  sunsetUtc: string;
  dayLengthSec: number;
}

interface SunApiResponse {
  results: {
    sunrise: string;
    sunset: string;
    day_length: number;
  };
  status: string;
}

// ── Moon phase ────────────────────────────────────────────────────────────────

/**
 * Phase 0..1 where 0 = new, 0.5 = full, 1 = new again.
 * Algorithm: synodic month against a known new moon (2000-01-06 18:14 UTC).
 */
function moonPhase(date = new Date()): number {
  const SYNODIC_MONTH = 29.530588853;
  const knownNewMoon = Date.UTC(2000, 0, 6, 18, 14) / 1000;
  const now = date.getTime() / 1000;
  const daysSince = (now - knownNewMoon) / 86_400;
  const phase = (daysSince / SYNODIC_MONTH) % 1;
  return phase < 0 ? phase + 1 : phase;
}

function moonIllumination(phase: number): number {
  return Math.round((1 - Math.cos(phase * 2 * Math.PI)) * 50);
}

function phaseKey(phase: number): string {
  if (phase < 0.03 || phase > 0.97) return 'astro.phase.new';
  if (phase < 0.22) return 'astro.phase.waxingCrescent';
  if (phase < 0.28) return 'astro.phase.firstQuarter';
  if (phase < 0.47) return 'astro.phase.waxingGibbous';
  if (phase < 0.53) return 'astro.phase.full';
  if (phase < 0.72) return 'astro.phase.waningGibbous';
  if (phase < 0.78) return 'astro.phase.lastQuarter';
  return 'astro.phase.waningCrescent';
}

function formatHHMM(iso: string | null): string {
  if (!iso) return '—';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '—';
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
}

function dayProgress(sunriseUtc: string | null, sunsetUtc: string | null): number {
  if (!sunriseUtc || !sunsetUtc) return 0;
  const now = Date.now();
  const rise = new Date(sunriseUtc).getTime();
  const set = new Date(sunsetUtc).getTime();
  if (now <= rise) return 0;
  if (now >= set) return 1;
  return (now - rise) / (set - rise);
}

// ── Moon glyph ────────────────────────────────────────────────────────────────

function MoonGlyph({ phase, size = 78 }: { phase: number; size?: number }) {
  const r = size / 2 - 2;
  const cx = size / 2;
  const cy = size / 2;
  const waxing = phase < 0.5;
  const k = waxing ? phase * 2 : (1 - phase) * 2;
  const ellipseR = r * (1 - k);
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
      <defs>
        <radialGradient id="atl-moon-glow" cx="50%" cy="45%" r="60%">
          <stop offset="0%" stopColor="#f2ecd8" />
          <stop offset="100%" stopColor="#c9c1a8" />
        </radialGradient>
        <mask id="atl-moon-mask">
          <rect width={size} height={size} fill="black" />
          <circle cx={cx} cy={cy} r={r} fill="white" />
          <ellipse cx={cx} cy={cy} rx={ellipseR} ry={r} fill="black" />
          <rect
            x={waxing ? 0 : cx}
            y={0}
            width={cx}
            height={size}
            fill="black"
          />
        </mask>
      </defs>
      <circle cx={cx} cy={cy} r={r} fill="#1f2233" stroke={theme.colors.borderSubtle} />
      <circle
        cx={cx}
        cy={cy}
        r={r}
        fill="url(#atl-moon-glow)"
        mask="url(#atl-moon-mask)"
        opacity="0.95"
      />
      <circle cx={cx - 8} cy={cy - 6} r="3" fill="#b8b099" opacity="0.25" mask="url(#atl-moon-mask)" />
      <circle cx={cx + 6} cy={cy + 10} r="4" fill="#b8b099" opacity="0.22" mask="url(#atl-moon-mask)" />
      <circle cx={cx - 3} cy={cy + 14} r="2" fill="#b8b099" opacity="0.25" mask="url(#atl-moon-mask)" />
    </svg>
  );
}

