// ── Component ────────────────────────────────────────────────────────────────

interface AstroWidgetProps {
  locale: string;
}

export function AstroWidget({ locale }: AstroWidgetProps) {
  const lang: Locale = locale === 'pt' ? 'pt' : 'en';
  const t = useMemo<TFunction>(() => createT(lang, SHELL_KEYS), [lang]);

  const [sun, setSun] = useState<SunData | null>(null);

  const fetchSun = useCallback(async () => {
    const today = new Date().toISOString().slice(0, 10);
    const cacheKey = `${CACHE_KEY_PREFIX}${today}`;
    const url = `https://api.sunrise-sunset.org/json?lat=${LAT}&lng=${LON}&formatted=0&date=${today}`;
    const result = await cachedFetch<SunApiResponse>(url, cacheKey);
    if (result?.results) {
      setSun({
        sunriseUtc: result.results.sunrise,
        sunsetUtc: result.results.sunset,
        dayLengthSec: result.results.day_length,
      });
    }
  }, []);

  useEffect(() => {
    fetchSun();
  }, [fetchSun]);

  const phase = moonPhase(new Date());
  const illum = moonIllumination(phase);
  const pKey = phaseKey(phase);

  const sunProgress = dayProgress(sun?.sunriseUtc ?? null, sun?.sunsetUtc ?? null);
  const sunX = 4 + sunProgress * 192;
  const sunY = 46 - Math.sin(sunProgress * Math.PI) * 42;

  const dayH = sun ? Math.floor(sun.dayLengthSec / 3600) : 0;
  const dayM = sun ? Math.floor((sun.dayLengthSec % 3600) / 60) : 0;

  return (
    <Wrapper>
      <Header>
        <Title>{t('astro.title')}</Title>
        <Accessory>{t('astro.location')}</Accessory>
      </Header>

      <MainGrid>
        <MoonCol>
          <MoonGlyph phase={phase} />
          <MoonCaption>{t('astro.illuminated', { pct: illum })}</MoonCaption>
        </MoonCol>
        <SunCol>
          <PhaseName>{t(pKey)}</PhaseName>
          <SunArcWrap>
            <svg viewBox="0 0 200 50" width="100%" height="44" style={{ display: 'block' }}>
              <path
                d="M 4 46 Q 100 -20 196 46"
                fill="none"
                stroke={theme.colors.borderSubtle}
                strokeWidth="1"
                strokeDasharray="2 3"
              />
              <circle cx={sunX} cy={sunY} r={3.5} fill="#e89a5c" />
              <line x1="4" y1="46" x2="4" y2="50" stroke={theme.colors.mainTextFaint} strokeWidth="1" />
              <line x1="196" y1="46" x2="196" y2="50" stroke={theme.colors.mainTextFaint} strokeWidth="1" />
            </svg>
          </SunArcWrap>
          <SunTimes>
            <span>↑ {formatHHMM(sun?.sunriseUtc ?? null)}</span>
            {sun && <DayLength>{t('astro.dayLength', { h: dayH, m: dayM })}</DayLength>}
            <span>↓ {formatHHMM(sun?.sunsetUtc ?? null)}</span>
          </SunTimes>
        </SunCol>
      </MainGrid>

      <IssSection>
        <IssTitle>{t('astro.iss.title')}</IssTitle>
        <IssEmpty>{t('astro.iss.empty')}</IssEmpty>
      </IssSection>
    </Wrapper>
  );
}
