import ReactDOM from 'react-dom';
import styled from '@emotion/styled';
import { keyframes } from '@emotion/react';
import { theme } from '@atlantis/shared';
import { Kbd } from '@atlantis/ui';
import type { TFunction } from '@atlantis/i18n';

const fadeIn = keyframes`
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: translateY(0); }
`;

const Pill = styled.button`
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: ${theme.zIndex.sticky};
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 12px 7px 14px;
  border-radius: 999px;
  background: ${theme.colors.surface};
  border: 1px solid ${theme.colors.border};
  box-shadow: ${theme.elevation.sm};
  color: ${theme.colors.mainTextMuted};
  font-family: ${theme.typography.fontFamily};
  font-size: 12px;
  line-height: 1;
  cursor: pointer;
  animation: ${fadeIn} 0.25s ${theme.transitions.easing} both;
  animation-delay: 1s;
  transition:
    border-color ${theme.transitions.fast},
    color ${theme.transitions.fast},
    transform ${theme.transitions.fast};

  &:hover {
    color: ${theme.colors.mainText};
    border-color: ${theme.colors.borderStrong};
    transform: translateY(-1px);
  }
  &:focus-visible { ${theme.focusRing} }

  /* Only precise-pointer devices see the hint — touch users have no
     keyboard, and the hint would cover content on phones. */
  @media (hover: none), (pointer: coarse) {
    display: none;
  }
`;

interface CmdKHintProps {
  onOpenPalette: () => void;
  t: TFunction;
}

/**
 * Bottom-right floating pill that reminds desktop users they can open the
 * command palette from anywhere via Cmd/Ctrl+K. Hidden on touch devices and
 * when the palette is already open (the parent controls visibility by
 * conditionally rendering this component).
 */
export function CmdKHint({ onOpenPalette, t }: CmdKHintProps) {
  return ReactDOM.createPortal(
    <Pill
      type="button"
      aria-label={t('cmdk.hint.aria')}
      onClick={onOpenPalette}
    >
      <Kbd>⌘K</Kbd>
      {t('cmdk.hint.label')}
    </Pill>,
    document.body,
  );
}
