import { theme, getLocalSetting, putLocalSetting } from '@atlantis/shared';
import { createT } from '@atlantis/i18n';
import type { Locale, TFunction } from '@atlantis/i18n';
import SHELL_KEYS from '../translations';

// ─── Dashboard-health channels ──────────────────────────────────────────────
//
// Every latency row corresponds to an API the home dashboard actually depends
// on, so "is this slow?" is a real signal, not trivia about random sites.

const HISTORY_LEN = 24;
const TICK_MS = 5_000;
const PING_CACHE_TTL = 60_000; // 1 minute between real pings per endpoint

interface ChannelDef {
  key: string;
  labelKey: string;
  color: string;
  unit: 'ms' | 'fps' | '';
  /** Scale range for the bar/sparkline — values outside are clamped */
  floor: number;
  ceil: number;
  /** Widgets that consume this endpoint — shown in the tooltip/meta row. */
  consumers?: string[];
}

const CHANNELS: ChannelDef[] = [
  { key: 'crypto',  labelKey: 'health.ch.crypto',  color: '#f7931a', unit: 'ms', floor: 0, ceil: 500, consumers: ['Crypto'] },
  { key: 'weather', labelKey: 'health.ch.weather', color: '#58a6ff', unit: 'ms', floor: 0, ceil: 500, consumers: ['Weather'] },
  { key: 'wiki',    labelKey: 'health.ch.wiki',    color: '#3fb950', unit: 'ms', floor: 0, ceil: 500, consumers: ['OnThisDay', 'WikiTop'] },
  { key: 'hn',      labelKey: 'health.ch.hn',      color: '#f97316', unit: 'ms', floor: 0, ceil: 500, consumers: ['TechScope', 'HN Hot'] },
  { key: 'dom',     labelKey: 'health.ch.dom',     color: '#f87171', unit: '',   floor: 0, ceil: 5000 },
  { key: 'fps',     labelKey: 'health.ch.fps',     color: '#d29922', unit: 'fps',floor: 0, ceil: 120 },
];

// Lightweight CORS-enabled endpoints that mirror what the real widgets fetch,
// so measured latency reflects actual user-perceived dashboard responsiveness.
const PING_ENDPOINTS: Record<string, string> = {
  crypto:  'https://api.coingecko.com/api/v3/ping',
  weather: 'https://api.open-meteo.com/v1/forecast?latitude=38.72&longitude=-9.14&current=temperature_2m',
  wiki:    'https://en.wikipedia.org/api/rest_v1/page/summary/Lisbon',
  hn:      'https://hn.algolia.com/api/v1/search?tags=front_page&hitsPerPage=1',
};

const PING_KEYS = Object.keys(PING_ENDPOINTS);

interface PingCacheEntry {
  latency: number;
  cachedAt: number;
}

/** Ping with cache — avoids rate limits by reusing recent measurements */
async function cachedPing(key: string, url: string): Promise<number> {
  const cacheKey = `widget-cache:ping-${key}`;
  const raw = await getLocalSetting(cacheKey);
  if (raw) {
    try {
      const entry: PingCacheEntry = JSON.parse(raw);
      if (Date.now() - entry.cachedAt < PING_CACHE_TTL) return entry.latency;
    } catch { /* stale — re-ping */ }
  }

  const t0 = performance.now();
  try {
    await fetch(url);
    const latency = Math.round(performance.now() - t0);
    const entry: PingCacheEntry = { latency, cachedAt: Date.now() };
    putLocalSetting(cacheKey, JSON.stringify(entry));
    return latency;
  } catch {
    return -1;
  }
}

function getDomNodeCount(): number {
  return document.getElementsByTagName('*').length;
}

// ─── FPS tracker ─────────────────────────────────────────────────────────────

function createFpsTracker() {
  let frames = 0;
  let lastTime = performance.now();
  let currentFps = 60;
  let rafId = 0;

  function loop() {
    frames++;
    const now = performance.now();
    const elapsed = now - lastTime;
    if (elapsed >= 1000) {
      currentFps = Math.round((frames * 1000) / elapsed);
      frames = 0;
      lastTime = now;
    }
    rafId = requestAnimationFrame(loop);
  }

  return {
    start() { rafId = requestAnimationFrame(loop); },
    stop() { cancelAnimationFrame(rafId); },
    get fps() { return currentFps; },
  };
}

