// ─── Component ───────────────────────────────────────────────────────────────

interface LiveDataWidgetProps {
  locale: string;
}

export function LiveDataWidget({ locale }: LiveDataWidgetProps) {
  const lang: Locale = locale === 'pt' ? 'pt' : 'en';
  const t = useMemo<TFunction>(() => createT(lang, SHELL_KEYS), [lang]);

  const [histories, setHistories] = useState<number[][]>(() =>
    CHANNELS.map(() => new Array<number>(HISTORY_LEN).fill(0)),
  );
  /** Per-channel offline flag — `true` when the most recent ping failed. */
  const [offline, setOffline] = useState<Record<string, boolean>>({});
  const [ready, setReady] = useState(false);
  const tickRef = useRef(0);
  const fpsRef = useRef<ReturnType<typeof createFpsTracker> | null>(null);

  // Start FPS tracker
  useEffect(() => {
    const tracker = createFpsTracker();
    fpsRef.current = tracker;
    tracker.start();
    return () => tracker.stop();
  }, []);

  // Tick: rotate through endpoints, always update local metrics
  const tick = useCallback(async () => {
    const currentTick = tickRef.current;
    tickRef.current += 1;

    // Rotate which endpoint to ping (1 per tick, cached to avoid rate limits)
    const pingKey = PING_KEYS[currentTick % PING_KEYS.length];
    const pingUrl = PING_ENDPOINTS[pingKey];
    const latency = await cachedPing(pingKey, pingUrl);
    const failed = latency < 0;

    // Local metrics
    const domCount = getDomNodeCount();
    const fps = fpsRef.current?.fps ?? 0;

    setOffline((prev) => ({ ...prev, [pingKey]: failed }));

    setHistories((prev) =>
      prev.map((hist, ci) => {
        const ch = CHANNELS[ci];
        let value: number;

        if (ch.key === pingKey) {
          // On failure, keep the previous reading alive so the sparkline
          // doesn't flatten to 0 — we signal the failure via `offline` instead.
          value = failed ? hist[hist.length - 1] : latency;
        } else if (ch.key === 'dom') {
          value = domCount;
        } else if (ch.key === 'fps') {
          value = fps;
        } else {
          // Not this endpoint's turn — keep last value
          return hist;
        }

        return [...hist.slice(1), value];
      }),
    );

    setReady(true);
  }, []);

  useEffect(() => {
    tick(); // initial
    const id = setInterval(tick, TICK_MS);
    return () => clearInterval(id);
  }, [tick]);

  if (!ready) {
    return (
      <Wrapper>
        <Placeholder>{t('health.measuring')}</Placeholder>
      </Wrapper>
    );
  }

  const OFFLINE_COLOR = theme.colors.mainTextFaint;

  // Aggregate status pill — reflects the *latency* channels only; DOM/FPS
  // don't influence the summary because they're always live locally.
  const offlineCount = Object.values(offline).filter(Boolean).length;
  const slowCount = CHANNELS.filter(
    (ch) => ch.unit === 'ms' && !offline[ch.key] && histories[CHANNELS.indexOf(ch)][HISTORY_LEN - 1] > 300,
  ).length;
  const statusTone: 'ok' | 'warn' | 'bad' = offlineCount > 0 ? 'bad' : slowCount > 0 ? 'warn' : 'ok';
  const statusLabel =
    offlineCount > 0
      ? t('health.status.offline', { n: offlineCount })
      : slowCount > 0
        ? t('health.status.slow', { n: slowCount })
        : t('health.status.ok');

  return (
    <Wrapper>
      <Header>
        <HeaderTitle>
          <LiveDot tone={statusTone} />
          {t('health.title')}
        </HeaderTitle>
        <StatusPill tone={statusTone}>{statusLabel}</StatusPill>
      </Header>
      <ChannelGrid>
        {CHANNELS.map((ch, ci) => {
          const hist = histories[ci];
          const current = hist[hist.length - 1];
          const prev = hist[hist.length - 2] ?? current;
          const isLatency = ch.unit === 'ms';
          const isOffline = isLatency && !!offline[ch.key];
          const warn = !isOffline && isLatency && current > 300;
          const pct = isOffline
            ? 100 /* full muted bar so it's visually distinct from 0ms */
            : ((current - ch.floor) / (ch.ceil - ch.floor)) * 100;

          const barColor = isOffline
            ? OFFLINE_COLOR
            : warn
              ? '#f85149'
              : ch.color;
          const valueColor = isOffline ? OFFLINE_COLOR : ch.color;

          const displayValue = isOffline
            ? t('health.offline')
            : ch.key === 'dom' && current >= 1000
              ? `${(current / 1000).toFixed(1)}k`
              : String(Math.round(current));
          const displayUnit = isOffline ? '' : ch.unit;

          // Trend: only meaningful once we have two non-zero readings.
          const delta = current - prev;
          const trendDir: 'up' | 'down' | 'flat' =
            !isOffline && Math.abs(delta) >= (isLatency ? 10 : 2)
              ? delta > 0 ? 'up' : 'down'
              : 'flat';
          const trendGlyph = trendDir === 'up' ? '▲' : trendDir === 'down' ? '▼' : '·';

          const consumerLabel = ch.consumers?.length
            ? t('health.consumers', { list: ch.consumers.join(' · ') })
            : '';

          return (
            <ChannelRow key={ch.key} delay={ci}>
              <ChannelTop>
                <ChannelLabelBlock>
                  <ChannelLabel>{t(ch.labelKey)}</ChannelLabel>
                  {consumerLabel && <ChannelConsumer>{consumerLabel}</ChannelConsumer>}
                </ChannelLabelBlock>
                <ValueGroup>
                  {!isOffline && trendDir !== 'flat' && (
                    <Trend dir={trendDir} latency={isLatency}>{trendGlyph}</Trend>
                  )}
                  <ChannelValue color={valueColor} warn={warn}>
                    {displayValue}
                    {displayUnit && <ChannelUnit>{displayUnit}</ChannelUnit>}
                  </ChannelValue>
                </ValueGroup>
              </ChannelTop>
              <BarTrack>
                <BarFill pct={pct} color={barColor} />
              </BarTrack>
              <SparkRow>
                {hist.map((v, j) => {
                  const h = Math.max(2, ((v - ch.floor) / (ch.ceil - ch.floor)) * 100);
                  return (
                    <SparkBar
                      key={j}
                      h={Math.min(100, h)}
                      color={
                        isOffline && j === hist.length - 1
                          ? OFFLINE_COLOR
                          : warn && j === hist.length - 1
                            ? '#f85149'
                            : ch.color
                      }
                      latest={j === hist.length - 1}
                    />
                  );
                })}
              </SparkRow>
            </ChannelRow>
          );
        })}
      </ChannelGrid>
    </Wrapper>
  );
}
